import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface LifeNode {
  id: string;
  name: string;
  birthDate: string;
  birthCountry: string;
  deathDate: string;
  deathPlace: string;
  deathCountry: string; // Used for continuity checks
  description: string;
  wikipediaUrl?: string;
  imageUrl?: string;
  loading?: boolean;
  isUser?: boolean; // To distinguish the starting point
}

export interface SearchParams {
  date: string; // YYYY-MM-DD
  country: string;
}

export interface GeminiPersonResponse {
  name: string;
  birthDate: string;
  birthCountry: string;
  deathDate: string;
  deathPlace: string;
  deathCountry: string;
  description: string;
  wikipediaQuery: string;
}

import { GoogleGenAI } from "@google/genai";
import { GeminiPersonResponse } from "../types";

const apiKey = process.env.API_KEY;

if (!apiKey) {
  console.error("API_KEY is not defined in the environment variables.");
}

const ai = new GoogleGenAI({ apiKey: apiKey || "" });

/**
 * Finds a historical figure who died on a specific date (or the day before)
 * prioritizing the given country, then continent, then world.
 */
export const findPreviousLife = async (
  targetDate: string,
  targetCountry: string,
  excludeNames: string[] = []
): Promise<GeminiPersonResponse | null> => {
  try {
    const model = 'gemini-3-flash-preview';

    const prompt = `
      I am creating a "Previous Lives" chain. 
      Find a famous historical figure (deceased) who died on ${targetDate} (YYYY-MM-DD).

      Rules:
      1. EXACT DATE MATCH PRIORITY: Try to find someone who died exactly on ${targetDate}.
      2. NEAR MATCH ALLOWED: If no one significant died on that exact day, you may choose someone who died the day before (${getDayBefore(targetDate)}).
      3. LOCATION PRIORITY:
         - First priority: Died in ${targetCountry}.
         - Second priority: Died in the same continent as ${targetCountry}.
         - Third priority: Died anywhere in the world.
      4. EXCLUSIONS: Do not choose any of these people: ${excludeNames.join(", ")}.
      5. DATA: You must find their Birth Date and Birth Country to continue the chain.

      Return a VALID JSON object inside a JSON code block. Structure:
      \`\`\`json
      {
        "name": "Full Name",
        "birthDate": "YYYY-MM-DD", (Use approximate if exact unknown, e.g. "1850-01-01")
        "birthCountry": "Country Name",
        "deathDate": "YYYY-MM-DD",
        "deathPlace": "City, Country",
        "deathCountry": "Country Name",
        "description": "A short, intriguing 2-sentence bio emphasizing their legacy.",
        "wikipediaQuery": "Name for Wikipedia Search"
      }
      \`\`\`
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
      },
    });

    const text = response.text;
    if (!text) return null;

    // Clean up markdown code blocks if present (though responseMimeType usually handles this)
    const jsonStr = text.replace(/```json\n?|\n?```/g, "").trim();

    try {
      const data = JSON.parse(jsonStr) as GeminiPersonResponse;
      return data;
    } catch (e) {
      console.error("Failed to parse Gemini JSON response", e);
      return null;
    }

  } catch (error) {
    console.error("Gemini API error:", error);
    throw error;
  }
};

function getDayBefore(dateStr: string): string {
  const date = new Date(dateStr);
  date.setDate(date.getDate() - 1);
  return date.toISOString().split('T')[0];
}

import React, { useState } from 'react';
