        </div>
        <h2 className="text-2xl font-serif font-bold text-mystic-100">Enter Your Origin</h2>
        <p className="text-mystic-300 mt-2 text-sm">The thread of history begins with you.</p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div>
          <label htmlFor="birthDate" className="block text-sm font-bold text-mystic-200 mb-2 uppercase tracking-wider">
            Date of Birth
          </label>
          <input
            id="birthDate"
            type="date"
            required
            value={date}
            onChange={(e) => setDate(e.target.value)}
            className="w-full px-4 py-3 bg-mystic-950 border border-mystic-700 rounded-lg focus:ring-2 focus:ring-mystic-500 focus:border-transparent text-mystic-100 outline-none transition-all"
          />
        </div>

        <div>
          <label htmlFor="country" className="block text-sm font-bold text-mystic-200 mb-2 uppercase tracking-wider">
            Country of Birth
