import React, { useEffect, useRef } from 'react';
import { LifeNode } from '../types';
import LifeCard from './LifeCard';

interface TimelineProps {
  lives: LifeNode[];
  onLoadNext: () => void;
  isLoadingNext: boolean;
}

const Timeline: React.FC<TimelineProps> = ({ lives, onLoadNext, isLoadingNext }) => {
  const bottomRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom when new life is added
  useEffect(() => {
    if (lives.length > 1 && !isLoadingNext) {
        bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [lives.length, isLoadingNext]);

  return (
    <div className="w-full max-w-4xl mx-auto px-4 py-8">
      <div className="flex flex-col items-center">
        {lives.map((life, index) => (
          <LifeCard 
            key={life.id} 
            life={life} 
            index={index} 
            isLast={index === lives.length - 1}
            onLoadNext={onLoadNext}
            isLoadingNext={isLoadingNext}
          />
        ))}
      </div>
      <div ref={bottomRef} className="h-4" />
    </div>
  );
};

export default Timeline;

import React, { useState } from 'react';
import { LifeNode, SearchParams } from './types';
import { findPreviousLife } from './services/geminiService';
import InputForm from './components/InputForm';
import Timeline from './components/Timeline';
import { History, RotateCcw } from 'lucide-react';

const App: React.FC = () => {
  const [lives, setLives] = useState<LifeNode[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const startChain = async (params: SearchParams) => {
    setLoading(true);
    setError(null);
    setLives([]);

    const userNode: LifeNode = {
      id: 'user',
      name: 'You',
      birthDate: params.date,
      birthCountry: params.country,
      deathDate: 'Present',
      deathPlace: 'Present',
      deathCountry: params.country, // Used for continuity
      description: 'The current manifestation of the soul.',
      isUser: true
    };

    setLives([userNode]);

    // Immediately find the first previous life
    await fetchNextLife(userNode, [userNode]);
  };

  const fetchNextLife = async (currentNode: LifeNode, currentLives: LifeNode[]) => {
    setLoading(true);
    setError(null);

    try {
      // Logic: Find someone who died on currentNode.birthDate (or day before)
      // in currentNode.birthCountry.
      const targetDate = currentNode.birthDate;
      const targetCountry = currentNode.birthCountry;

      const excludeNames = currentLives.map(l => l.name);

      const result = await findPreviousLife(targetDate, targetCountry, excludeNames);

      if (result) {
        const newNode: LifeNode = {
          id: `life-${Date.now()}`,
          name: result.name,
          birthDate: result.birthDate,
          birthCountry: result.birthCountry,
          deathDate: result.deathDate,
          deathPlace: result.deathPlace,
          deathCountry: result.deathCountry,
          description: result.description,
          wikipediaUrl: `https://en.wikipedia.org/wiki/${encodeURIComponent(result.wikipediaQuery)}`,
          isUser: false
        };

        setLives(prev => [...prev, newNode]);
      } else {
        // Handle "End of the line"
        setError("The threads of history fade into obscurity here. No further records could be found.");
      }
    } catch (err) {
      console.error(err);
      setError("The cosmic archives are currently unreachable. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleLoadNext = () => {
    if (lives.length > 0) {
      const lastLife = lives[lives.length - 1];
      fetchNextLife(lastLife, lives);
    }
  };

  const handleReset = () => {
    setLives([]);
    setError(null);
    setLoading(false);
  };

  return (
    <div className="min-h-screen bg-mystic-950 text-mystic-50 font-sans selection:bg-mystic-500 selection:text-white pb-20">
      {/* Header */}
      <header className="p-6 border-b border-mystic-800 bg-mystic-950/80 backdrop-blur sticky top-0 z-50">
        <div className="max-w-6xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="bg-mystic-800 p-2 rounded-full border border-mystic-600">
                <History className="w-6 h-6 text-mystic-300" />
             </div>
             <h1 className="text-2xl font-serif font-bold tracking-wide text-white">My Previous Lives</h1>
          </div>
          {lives.length > 0 && (
            <button 
              onClick={handleReset}
              className="flex items-center gap-2 text-sm text-mystic-400 hover:text-white transition-colors"
            >
              <RotateCcw className="w-4 h-4" /> Start Over
            </button>
          )}
        </div>
      </header>

      {/* Main Content */}
      <main className="container mx-auto px-4 pt-12">
        {lives.length === 0 ? (
          <div className="max-w-xl mx-auto mt-10">
            <InputForm onSubmit={startChain} isLoading={loading} />

            <div className="mt-12 text-center text-mystic-400 text-sm">
              <p className="font-serif italic opacity-70">
                "Life is a tapestry woven by the threads of time."
              </p>
            </div>
          </div>
        ) : (
          <div className="relative">
             <Timeline 
                lives={lives} 
                onLoadNext={handleLoadNext} 
                isLoadingNext={loading} 
             />

             {error && (
                <div className="max-w-lg mx-auto mt-8 p-4 bg-red-900/30 border border-red-800/50 rounded-lg text-red-200 text-center animate-fade-in-up">
                    <p>{error}</p>
                    <button 
                        onClick={handleLoadNext}
                        className="mt-2 text-sm underline hover:text-white"
                    >
                        Try connecting again
                    </button>
                </div>
             )}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

