}

const ai = new GoogleGenAI({ apiKey: apiKey || "" });

/**
 * Finds historical figures who died on a specific date (or the day before)
 * prioritizing the given country, then continent, then world.
 */
export const findPreviousLifeCandidates = async (
  targetDate: string,
  targetCountry: string,
  excludeNames: string[] = []
): Promise<GeminiPersonResponse[]> => {
  try {
    const model = 'gemini-3-flash-preview';

    const prompt = `
      I am creating a "Previous Lives" chain. 
      Find up to 2 distinct famous historical figures (deceased) who died on ${targetDate} (YYYY-MM-DD).

      Rules:
      1. EXACT DATE MATCH PRIORITY: Try to find people who died exactly on ${targetDate}.
      2. NEAR MATCH ALLOWED: If exact matches are scarce, you may choose someone who died the day before (${getDayBefore(targetDate)}).
      3. LOCATION PRIORITY:
         - First priority: Died in ${targetCountry}.
         - Second priority: Died in the same continent as ${targetCountry}.
         - Third priority: Died anywhere in the world.
      4. EXCLUSIONS: Do not choose any of these people: ${excludeNames.join(", ")}.
      5. DATA: You must find their Birth Date and Birth Country to continue the chain.

      Return a VALID JSON ARRAY inside a JSON code block. Example Structure:
      \`\`\`json
      [
        {
          "name": "Full Name",
          "birthDate": "YYYY-MM-DD",
          "birthCountry": "Country Name",
          "deathDate": "YYYY-MM-DD",
          "deathPlace": "City, Country",
          "deathCountry": "Country Name",
          "description": "A short, intriguing 2-sentence bio emphasizing their legacy.",
          "wikipediaQuery": "Name for Wikipedia Search"
        }
      ]
      \`\`\`
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
      },
    });

    const text = response.text;
    if (!text) return [];

    const jsonStr = text.replace(/```json\n?|\n?```/g, "").trim();

    try {
      // Handle both array and single object responses gracefully
      const parsed = JSON.parse(jsonStr);
      if (Array.isArray(parsed)) {
        return parsed as GeminiPersonResponse[];
      } else if (typeof parsed === 'object' && parsed !== null) {
        return [parsed as GeminiPersonResponse];
      }
      return [];
