import React, { useState, useRef } from 'react';
import { ChevronLeft, ChevronRight, Calendar } from 'lucide-react';

interface CustomDatePickerProps {
  value: string;
  onChange: (date: string) => void;
}

const MONTH_NAMES = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"
];

const CustomDatePicker: React.FC<CustomDatePickerProps> = ({ value, onChange }) => {
  const currentYear = new Date().getFullYear();
  // Start in 'year' mode if no date is selected yet
  const [mode, setMode] = useState<'year' | 'date'>(value ? 'date' : 'year');
  // Initialize viewDate to the passed value or today.
  // We use this to track which Month/Year is being viewed in the calendar or year selector.
  const [viewDate, setViewDate] = useState(() => {
    if (value) {
        // value is YYYY-MM-DD
        const [y, m, d] = value.split('-').map(Number);
        return new Date(y, m - 1, d);
    }
    return new Date();
  });

  // Year Scroll Logic: 1900 to Current Year
  const years = Array.from({ length: currentYear - 1900 + 1 }, (_, i) => currentYear - i);
  const yearScrollRef = useRef<HTMLDivElement>(null);

  // Calendar Logic
  const daysInMonth = new Date(viewDate.getFullYear(), viewDate.getMonth() + 1, 0).getDate();
  const firstDayOfMonth = new Date(viewDate.getFullYear(), viewDate.getMonth(), 1).getDay();

  const handleYearSelect = (year: number) => {
    const newDate = new Date(viewDate);
    newDate.setFullYear(year);
    setViewDate(newDate);
    setMode('date');
  };

  const handleMonthChange = (offset: number) => {
    const newDate = new Date(viewDate);
    newDate.setMonth(newDate.getMonth() + offset);
    setViewDate(newDate);
  };

  const handleDaySelect = (day: number) => {
    // Construct YYYY-MM-DD string
    // Note: Month is 0-indexed in JS Date, so add 1
    const year = viewDate.getFullYear();
    const month = String(viewDate.getMonth() + 1).padStart(2, '0');
    const dayStr = String(day).padStart(2, '0');
    onChange(`${year}-${month}-${dayStr}`);
  };

  // Check if a day is selected to highlight it
  const isSelected = (day: number) => {
    if (!value) return false;
    const [y, m, d] = value.split('-').map(Number);
    return y === viewDate.getFullYear() && m === viewDate.getMonth() + 1 && d === day;
  };

  return (
    <div className="w-full bg-mystic-950 border border-mystic-700 rounded-lg overflow-hidden shadow-[inset_0_2px_4px_rgba(0,0,0,0.3)]">
      {/* Header / Toggle */}
      <div className="bg-mystic-900 p-3 flex justify-between items-center border-b border-mystic-800 h-14">
        <button 
          type="button"
          className="flex items-center gap-2 text-mystic-100 font-bold cursor-pointer hover:text-mystic-300 transition-colors focus:outline-none"
          onClick={() => setMode('year')}
        >
          <Calendar className="w-4 h-4" />
          <span className="font-serif tracking-wide">
            {mode === 'year' ? 'Select Year' : `${MONTH_NAMES[viewDate.getMonth()]} ${viewDate.getFullYear()}`}
          </span>
        </button>

        {mode === 'date' && (
           <div className="flex gap-1">
             <button 
                type="button"
                onClick={() => handleMonthChange(-1)}
                className="p-1 hover:bg-mystic-800 rounded text-mystic-300 hover:text-white transition-colors"
             >
               <ChevronLeft className="w-5 h-5" />
             </button>
             <button 
                type="button"
                onClick={() => handleMonthChange(1)}
                className="p-1 hover:bg-mystic-800 rounded text-mystic-300 hover:text-white transition-colors"
             >
               <ChevronRight className="w-5 h-5" />
             </button>
           </div>
        )}
      </div>

      <div className="h-72 relative bg-mystic-900">
        {mode === 'year' ? (
          <div className="h-full overflow-y-auto scrollbar-thin scrollbar-thumb-mystic-700 scrollbar-track-transparent snap-y py-20" ref={yearScrollRef}>
            {years.map(year => (
              <div 
                key={year}
                onClick={() => handleYearSelect(year)}
                className={`
                  snap-center py-3 text-center cursor-pointer transition-all duration-200 font-serif
                  ${viewDate.getFullYear() === year 
                    ? 'text-white font-bold text-2xl scale-110' 
                    : 'text-mystic-500 hover:text-mystic-200 text-lg'}
                `}
              >
                {year}
              </div>
            ))}
          </div>
        ) : (
          <div className="p-4 h-full flex flex-col animate-fade-in-up">
            <div className="grid grid-cols-7 mb-2 text-center">
              {['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'].map(d => (
                <div key={d} className="text-xs font-bold text-mystic-500 uppercase tracking-widest">{d}</div>
              ))}
            </div>
            <div className="grid grid-cols-7 gap-1 auto-rows-fr flex-1">
              {/* Empty slots */}
              {Array.from({ length: firstDayOfMonth }).map((_, i) => (
                <div key={`empty-${i}`} />
              ))}
              {/* Days */}
              {Array.from({ length: daysInMonth }).map((_, i) => {
                const day = i + 1;
                const selected = isSelected(day);
                return (
                  <button
                    key={day}
                    type="button"
                    onClick={() => handleDaySelect(day)}
                    className={`
                      rounded-md text-sm font-medium transition-all duration-200
                      ${selected 
                        ? 'bg-mystic-600 text-white shadow-lg scale-110 font-bold border border-mystic-400' 
                        : 'text-mystic-200 hover:bg-mystic-800 hover:text-white'}
                    `}
                  >
                    {day}
                  </button>
                );
              })}
            </div>
             <div className="mt-2 text-center border-t border-mystic-800 pt-2">
                 <button 
                    type="button" 
                    onClick={() => setMode('year')}
                    className="text-xs text-mystic-500 hover:text-mystic-300 uppercase tracking-widest hover:underline"
                 >
                    Change Year
                 </button>
             </div>
          </div>
        )}

        {/* Gradient overlays for year scroll to simulate wheel effect */}
        {mode === 'year' && (
            <>
                <div className="absolute top-0 left-0 right-0 h-24 bg-gradient-to-b from-mystic-900 to-transparent pointer-events-none" />
                <div className="absolute bottom-0 left-0 right-0 h-24 bg-gradient-to-t from-mystic-900 to-transparent pointer-events-none" />
            </>
        )}
      </div>
    </div>
  );
};

