import { GoogleGenAI } from "@google/genai";
import { GeminiPersonResponse } from "../types";

const apiKey = process.env.API_KEY;

if (!apiKey) {
  console.error("API_KEY is not defined in the environment variables.");
}

const ai = new GoogleGenAI({ apiKey: apiKey || "" });

// Use the fastest model available for quick interactions
const MODEL_FAST = 'gemini-2.5-flash-latest'; 
const MODEL_REASONING = 'gemini-3-flash-preview'; // Good balance for the main search

/**
 * Finds historical figures who died on a specific date (or the day before)
 * prioritizing the given country, then continent, then world.
 */
export const findPreviousLifeCandidates = async (
  targetDate: string,
  deathCountry: string,
  excludeNames: string[] = []
): Promise<GeminiPersonResponse[]> => {
  try {
    const prompt = `
      Find 2 famous deceased historical figures who died on ${targetDate} (YYYY-MM-DD).

      Priorities:
      1. Exact date match > Day before match (${getDayBefore(targetDate)}).
      2. Died in ${deathCountry} > Same Continent > World.
      3. NOT in: ${excludeNames.join(", ")}.

      Output JSON array:
      [{
        "name": "Name",
        "birthDate": "YYYY-MM-DD",
        "birthCountry": "Country",
        "deathDate": "YYYY-MM-DD",
        "deathPlace": "City, Country",
        "deathCountry": "Country",
        "description": "2 intriguing sentences.",
        "wikipediaQuery": "Wiki Title"
      }]
    `;

    const response = await ai.models.generateContent({
      model: MODEL_REASONING,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
      },
    });

    const text = response.text;
    if (!text) return [];

    const jsonStr = text.replace(/```json\n?|\n?```/g, "").trim();

    try {
      const parsed = JSON.parse(jsonStr);
      if (Array.isArray(parsed)) return parsed as GeminiPersonResponse[];
      if (typeof parsed === 'object' && parsed !== null) return [parsed as GeminiPersonResponse];
      return [];
    } catch (e) {
      console.error("JSON parse error", e);
      return [];
    }

  } catch (error) {
    console.error("Gemini API error:", error);
    throw error;
  }
};

/**
 * Fetches 4 short historical event headlines that happened during the person's life
 * within their region.
 */
export const getHistoricalEvents = async (
    birthYear: string,
    deathYear: string,
    country: string
): Promise<string[]> => {
    try {
        // Fallback for "Present" death dates
        if (deathYear === 'Present') {
            deathYear = new Date().getFullYear().toString();
        }

        const prompt = `
            List 4 major historical events that happened between ${birthYear} and ${deathYear}.
            Focus on events relevant to ${country} or the surrounding region. 
            If ${country} is obscure, use major world events.
            Format: "Event Name (Year)" or "Event Name (Year-Year)".
            Keep it very brief (max 10 words per event).
            Return a JSON array of strings.
        `;

        const response = await ai.models.generateContent({
            model: MODEL_FAST, // Use the fastest model for these balloons
            contents: prompt,
            config: {
                responseMimeType: "application/json",
            }
        });

        const text = response.text;
        if (!text) return [];

        const jsonStr = text.replace(/```json\n?|\n?```/g, "").trim();
        const parsed = JSON.parse(jsonStr);
        return Array.isArray(parsed) ? parsed.slice(0, 4) : [];
    } catch (error) {
        console.warn("Failed to fetch historical events", error);
        return [];
    }
}

function getDayBefore(dateStr: string): string {
  const date = new Date(dateStr);
  date.setDate(date.getDate() - 1);
  return date.toISOString().split('T')[0];
}

import React, { useState, useEffect } from 'react';
import { LifeNode, SearchParams, GeminiPersonResponse } from './types';
import { findPreviousLifeCandidates, getHistoricalEvents } from './services/geminiService';
import InputForm from './components/InputForm';
import Timeline from './components/Timeline';
import SelectionArea from './components/SelectionArea';
import { History, RotateCcw } from 'lucide-react';

const App: React.FC = () => {
  const [lives, setLives] = useState<LifeNode[]>([]);
  const [candidates, setCandidates] = useState<GeminiPersonResponse[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const startChain = async (params: SearchParams) => {
    setLoading(true);
    setError(null);
    setLives([]);
    setCandidates([]);

    const userNode: LifeNode = {
      id: 'user',
      name: 'You',
      birthDate: params.date,
      birthCountry: params.country,
      deathDate: 'Present',
      deathPlace: 'Present',
      deathCountry: params.country,
      description: 'The current manifestation of the soul.',
      isUser: true
    };

    setLives([userNode]);

    // For the user, we don't strictly need historical events of their "previous" life yet,
    // but we could fetch events of their *current* life (birth to present).
    // Let's just fetch candidates.
    await fetchCandidatesForNode(userNode, [userNode]);
  };

  const fetchCandidatesForNode = async (currentNode: LifeNode, currentLives: LifeNode[]) => {
    setLoading(true);
    setError(null);
    setCandidates([]);

    try {
      const targetDate = currentNode.birthDate;
      const locationConstraint = currentNode.deathCountry || currentNode.birthCountry;
      const excludeNames = currentLives.map(l => l.name);

      const results = await findPreviousLifeCandidates(targetDate, locationConstraint, excludeNames);

      if (results && results.length > 0) {
        setCandidates(results);
      } else {
        setError("The threads of history fade into obscurity here. No further records could be found.");
      }
    } catch (err) {
      console.error(err);
      setError("The cosmic archives are currently unreachable. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleSelectCandidate = async (candidate: GeminiPersonResponse) => {
    const newNode: LifeNode = {
      id: `life-${Date.now()}`,
      name: candidate.name,
      birthDate: candidate.birthDate,
      birthCountry: candidate.birthCountry,
      deathDate: candidate.deathDate,
      deathPlace: candidate.deathPlace,
      deathCountry: candidate.deathCountry,
      description: candidate.description,
      wikipediaUrl: `https://en.wikipedia.org/wiki/${encodeURIComponent(candidate.wikipediaQuery)}`,
      isUser: false
    };

    const newLives = [...lives, newNode];
    setLives(newLives);
    setCandidates([]); // Clear selection

    // Parallel Execution:
    // 1. Fetch historical events for the NEW node (to display balloons while waiting).
    // 2. Fetch NEXT candidates.

    // We don't await the events here to block the UI, but we want them to appear asap.
    // We trigger both.

    const eventsPromise = fetchEventsForNode(newNode);
    const candidatesPromise = fetchCandidatesForNode(newNode, newLives);

    await Promise.all([eventsPromise, candidatesPromise]);
  };

  const fetchEventsForNode = async (node: LifeNode) => {
      const birthYear = node.birthDate.split('-')[0];
      const deathYear = node.deathDate === 'Present' ? new Date().getFullYear().toString() : node.deathDate.split('-')[0];

      const events = await getHistoricalEvents(birthYear, deathYear, node.deathCountry);

      // Update state with events
      setLives(prevLives => prevLives.map(l => 
          l.id === node.id ? { ...l, historicalEvents: events } : l
      ));
  };

  const handleShuffle = () => {
    if (lives.length > 0) {
      const lastLife = lives[lives.length - 1];
      fetchCandidatesForNode(lastLife, lives);
    }
  };

  const handleReset = () => {
    setLives([]);
    setCandidates([]);
    setError(null);
    setLoading(false);
  };

  return (
    <div className="min-h-screen bg-mystic-950 text-mystic-50 font-sans selection:bg-mystic-500 selection:text-white pb-20 overflow-x-hidden">
      {/* Header */}
      <header className="p-6 border-b border-mystic-800 bg-mystic-950/80 backdrop-blur sticky top-0 z-50">
        <div className="max-w-6xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="bg-mystic-800 p-2 rounded-full border border-mystic-600">
                <History className="w-6 h-6 text-mystic-300" />
             </div>
             <h1 className="text-2xl font-serif font-bold tracking-wide text-white">My Previous Lives</h1>
          </div>
          {lives.length > 0 && (
            <button 
              onClick={handleReset}
              className="flex items-center gap-2 text-sm text-mystic-400 hover:text-white transition-colors"
            >
              <RotateCcw className="w-4 h-4" /> Start Over
            </button>
          )}
        </div>
      </header>

      {/* Main Content */}
      <main className="container mx-auto px-4 pt-12 flex flex-col items-center">
        {lives.length === 0 ? (
          <div className="max-w-xl w-full mx-auto mt-10">
            <InputForm onSubmit={startChain} isLoading={loading} />

            <div className="mt-12 text-center text-mystic-400 text-sm">
              <p className="font-serif italic opacity-70">
                "Life is a tapestry woven by the threads of time."
              </p>
            </div>
          </div>
        ) : (
          <div className="relative w-full max-w-4xl">
             <Timeline lives={lives} />

             {/* The Selection Area appears at the end of the timeline */}
             <div className="mt-4">
                {(loading || candidates.length > 0 || error) && (
                   <SelectionArea 
                      candidates={candidates}
                      isLoading={loading}
                      onSelect={handleSelectCandidate}
                      onShuffle={handleShuffle}
                   />
                )}
             </div>

             {error && !loading && candidates.length === 0 && (
                <div className="max-w-lg mx-auto mt-8 p-4 bg-red-900/30 border border-red-800/50 rounded-lg text-red-200 text-center animate-fade-in-up">
                    <p>{error}</p>
                    <button 
                        onClick={handleShuffle}
                        className="mt-2 text-sm underline hover:text-white"
                    >
                        Try connecting again
                    </button>
                </div>
             )}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { LifeNode } from '../types';
import { MapPin, Calendar, ExternalLink, Skull } from 'lucide-react';

interface LifeCardProps {
  life: LifeNode;
  index: number;
  isLast: boolean;
}

const LifeCard: React.FC<LifeCardProps> = ({ life, index, isLast }) => {
  // Stagger animation delay based on index for the main card
  const animationDelay = `${index * 0.2}s`;

  // Specific styling for balloon positions to match the "around the card" request
  const balloonPositions = [
    "top-0 -left-4 md:-left-32 -translate-y-full md:translate-y-0", // Top Left
    "top-0 -right-4 md:-right-32 -translate-y-full md:translate-y-0", // Top Right
    "bottom-0 -left-4 md:-left-32 translate-y-full md:translate-y-0", // Bottom Left
    "bottom-0 -right-4 md:-right-32 translate-y-full md:translate-y-0"  // Bottom Right
  ];

  if (life.isUser) {
    return (
      <div 
        className="relative flex flex-col items-center animate-fade-in-up w-full" 
        style={{ animationDelay }}
      >
        <div className="z-10 w-full max-w-2xl bg-gradient-to-br from-mystic-800 to-mystic-900 border-2 border-mystic-500 rounded-xl p-6 shadow-[0_0_30px_rgba(129,84,175,0.2)]">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-xl font-serif font-bold text-white">Your Current Incarnation</h3>
            <span className="px-3 py-1 bg-mystic-700 rounded-full text-xs font-bold text-mystic-200">PRESENT</span>
          </div>
          <div className="space-y-2 text-mystic-200">
            <div className="flex items-center gap-2">
              <Calendar className="w-4 h-4 text-mystic-400" />
              <span>Born: <span className="text-white font-semibold">{life.birthDate}</span></span>
