        {/* Connector Line */}
        <div className="h-12 w-0.5 bg-gradient-to-b from-mystic-500 to-mystic-700 my-2"></div>
      </div>
    );
  }

  return (
    <div 
      className="relative flex flex-col items-center w-full animate-fade-in-up"
      style={{ animationDelay: isLast ? '0s' : animationDelay }} 
    >
      <div className="relative z-10 w-full max-w-2xl">

          {/* Historical Event Balloons */}
          {life.historicalEvents && life.historicalEvents.map((event, i) => (
             <div 
                key={i}
                className={`
                    absolute z-0 hidden md:flex items-center w-48
                    ${i % 2 === 0 ? 'justify-end text-right' : 'justify-start text-left'}
                    animate-fade-in-up
                    ${balloonPositions[i % 4]}
                `}
                style={{ animationDelay: `${i * 0.5 + 0.5}s` }} // Gradual pop up
             >
                {/* Connector Line (pseudo-arrow) */}
                <div className={`
                    absolute top-1/2 w-8 h-px bg-mystic-500
                    ${i % 2 === 0 ? '-right-8' : '-left-8'}
                `}></div>

                <div className="bg-mystic-900/80 backdrop-blur border border-mystic-500 p-3 rounded-lg shadow-lg text-xs font-serif text-mystic-200 leading-tight">
                    {event}
                </div>
             </div>
          ))}

          {/* Main Card */}
          <div className="relative z-10 bg-parchment text-gray-900 rounded-xl overflow-hidden shadow-2xl border border-mystic-300">
            <div className="bg-mystic-100 p-4 border-b border-mystic-200 flex justify-between items-start">
                <div>
                    <h3 className="text-2xl font-serif font-bold text-mystic-900">{life.name}</h3>
                    <div className="flex items-center gap-2 text-mystic-800 text-sm mt-1">
                        <MapPin className="w-3 h-3" />
                        <span>{life.birthCountry}</span>
                    </div>
                </div>
                {life.wikipediaUrl && (
                    <a 
                        href={life.wikipediaUrl} 
                        target="_blank" 
                        rel="noopener noreferrer"
                        className="text-mystic-600 hover:text-mystic-800 transition-colors"
                        title="Read on Wikipedia"
                    >
                        <ExternalLink className="w-5 h-5" />
                    </a>
                )}
            </div>

            <div className="p-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-4">
                    <div className="bg-white/50 p-3 rounded-lg border border-mystic-200">
                        <div className="flex items-center gap-2 text-mystic-700 mb-1 font-bold text-xs uppercase tracking-wider">
                            <Calendar className="w-3 h-3" /> Birth
                        </div>
                        <div className="font-serif text-lg">{life.birthDate}</div>
                        <div className="text-sm text-gray-600">{life.birthCountry}</div>
                    </div>
                    <div className="bg-mystic-50/50 p-3 rounded-lg border border-mystic-200">
                        <div className="flex items-center gap-2 text-red-800 mb-1 font-bold text-xs uppercase tracking-wider">
                            <Skull className="w-3 h-3" /> Death
                        </div>
                        <div className="font-serif text-lg">{life.deathDate}</div>
                        <div className="text-sm text-gray-600">{life.deathPlace}</div>
                    </div>
                </div>

                <p className="text-gray-700 font-serif leading-relaxed italic border-l-4 border-mystic-400 pl-4 py-1">
                    "{life.description}"
                </p>

                <div className="mt-4 pt-4 border-t border-gray-200 text-xs text-gray-500 text-center">
                    Reincarnated as next soul on {life.deathDate}
                </div>
            </div>
          </div>
      </div>

      {/* Connection Logic */}
      <div className="h-12 w-0.5 bg-gradient-to-b from-mystic-700 to-mystic-500 my-2"></div>
    </div>
  );
};

