  // We use separate states for flexible input handling
  const [day, setDay] = useState('');
  const [month, setMonth] = useState('');
  const [year, setYear] = useState('');
  const [country, setCountry] = useState('');

  // Derived full date for validation/submission
  const getFullDate = () => {
    if (!day || !month || !year || year.length < 4) return '';
    return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const dateStr = getFullDate();
    if (dateStr && country) {
      onSubmit({ date: dateStr, country });
    }
  };

  // Year handling logic requested: overwrite if full
  const handleYearKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    // Check if key is a number
    if (/^[0-9]$/.test(e.key)) {
      if (year.length === 4) {
        // If selection is collapsed (no text selected), overwrite
        const target = e.target as HTMLInputElement;
        if (target.selectionStart === target.selectionEnd) {
          e.preventDefault();
          setYear(e.key);
        }
      }
    }
  };

  const handleYearChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value.replace(/\D/g, '');
      if (val.length <= 4) {
