// Use the fastest model available for quick interactions
const MODEL_FAST = 'gemini-2.5-flash-latest'; 
const MODEL_REASONING = 'gemini-3-flash-preview'; // Good balance for the main search

// Retry helper
async function retryOperation<T>(operation: () => Promise<T>, retries = 3, delay = 1000): Promise<T> {
  try {
    return await operation();
  } catch (error) {
    if (retries <= 0) throw error;
    console.warn(`Retrying operation... Attempts left: ${retries}. Error:`, error);
    await new Promise(r => setTimeout(r, delay));
    return retryOperation(operation, retries - 1, delay * 2);
  }
}

/**
 * Finds historical figures who died on a specific date (or the day before)
 * prioritizing the given country, then continent, then world.
 */
export const findPreviousLifeCandidates = async (
