interface LifeCardProps {
  life: LifeNode;
  index: number;
  isLast: boolean;
  stopBubbles: boolean; // Signal to stop showing new bubbles
}

const LifeCard: React.FC<LifeCardProps> = ({ life, index, isLast, stopBubbles }) => {
  const [visibleBubbles, setVisibleBubbles] = useState<number>(0);

  // Stagger animation delay based on index for the main card
  const animationDelay = `${index * 0.2}s`;

  // Revised balloon positions: Pushed further out and larger dimensions
  const balloonPositions = [
    "top-[-2rem] left-[-2rem] md:top-10 md:left-[-14rem] md:text-right md:justify-end origin-bottom-right", 
    "top-[-2rem] right-[-2rem] md:top-10 md:right-[-14rem] md:text-left md:justify-start origin-bottom-left", 
    "bottom-[-2rem] left-[-2rem] md:bottom-20 md:left-[-14rem] md:text-right md:justify-end origin-top-right", 
    "bottom-[-2rem] right-[-2rem] md:bottom-20 md:right-[-14rem] md:text-left md:justify-start origin-top-left"
  ];

  // Logic to show bubbles one by one
  useEffect(() => {
    if (!isLast || !life.historicalEvents) return;

    // Reset if it's a new life node (re-mount)
    setVisibleBubbles(0);

    const interval = setInterval(() => {
        if (stopBubbles) {
            clearInterval(interval);
            return;
