import React, { useEffect, useRef, useState } from 'react';
import { LifeNode } from '../types';
import LifeCard from './LifeCard';
import { ZoomIn, ZoomOut } from 'lucide-react';

interface TimelineProps {
  lives: LifeNode[];
  candidatesReady: boolean; // Prop to know if next candidates are found
}

const Timeline: React.FC<TimelineProps> = ({ lives, candidatesReady }) => {
  const bottomRef = useRef<HTMLDivElement>(null);
  const [scale, setScale] = useState(1);

  // Auto-scroll to bottom when new life is added
  useEffect(() => {
    if (lives.length > 0) {
      setTimeout(() => {
        bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
      }, 100);
    }
  }, [lives.length]);

  const handleZoomIn = () => {
    setScale(prev => Math.min(prev + 0.1, 1.2));
  };

  const handleZoomOut = () => {
    setScale(prev => Math.max(prev - 0.2, 0.4));
  };

  return (
    <div className="w-full max-w-4xl mx-auto px-4 py-8 relative">

      {/* Zoom Controls */}
      <div className="fixed bottom-6 right-6 z-50 flex flex-col gap-2 bg-mystic-900/80 backdrop-blur-md p-2 rounded-lg border border-mystic-700 shadow-xl">
        <button 
          onClick={handleZoomIn}
          disabled={scale >= 1.2}
          className="p-2 hover:bg-mystic-700 rounded-md text-mystic-200 disabled:opacity-50 transition-colors"
          title="Zoom In"
        >
          <ZoomIn className="w-5 h-5" />
        </button>
        <div className="h-px bg-mystic-700 w-full"></div>
        <button 
          onClick={handleZoomOut}
          disabled={scale <= 0.4}
          className="p-2 hover:bg-mystic-700 rounded-md text-mystic-200 disabled:opacity-50 transition-colors"
          title="Zoom Out"
        >
          <ZoomOut className="w-5 h-5" />
        </button>
        <div className="text-[10px] text-center text-mystic-500 font-mono">
            {Math.round(scale * 100)}%
        </div>
      </div>

      <div 
        className="flex flex-col items-center transition-transform duration-300 origin-top"
        style={{ transform: `scale(${scale})` }}
      >
        {lives.map((life, index) => (
          <LifeCard 
            key={life.id} 
            life={life} 
            index={index} 
            isLast={index === lives.length - 1}
            stopBubbles={candidatesReady} // Stop bubbles if next choice is ready
          />
        ))}
      </div>
      <div ref={bottomRef} className="h-4" />
    </div>
  );
};

export default Timeline;

import React, { useState, useEffect } from 'react';
import { LifeNode, SearchParams, GeminiPersonResponse } from './types';
import { findPreviousLifeCandidates, getHistoricalEvents } from './services/geminiService';
import InputForm from './components/InputForm';
import Timeline from './components/Timeline';
import SelectionArea from './components/SelectionArea';
import { History, RotateCcw, RefreshCw } from 'lucide-react';

const App: React.FC = () => {
  const [lives, setLives] = useState<LifeNode[]>([]);
  const [candidates, setCandidates] = useState<GeminiPersonResponse[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Store initial params for the "Restart" feature
  const [initialParams, setInitialParams] = useState<SearchParams | null>(null);

  const startChain = async (params: SearchParams) => {
    setLoading(true);
    setError(null);
    setLives([]);
    setCandidates([]);
    setInitialParams(params);

    const userNode: LifeNode = {
      id: 'user',
      name: 'You',
      birthDate: params.date,
      birthCountry: params.country,
      deathDate: 'Present',
      deathPlace: 'Present',
      deathCountry: params.country,
      description: 'The current manifestation of the soul.',
      isUser: true
    };

    setLives([userNode]);

    await fetchCandidatesForNode(userNode, [userNode]);
  };

  const fetchCandidatesForNode = async (currentNode: LifeNode, currentLives: LifeNode[]) => {
    setLoading(true);
    setError(null);
    setCandidates([]);

    try {
      const targetDate = currentNode.birthDate;
      const locationConstraint = currentNode.deathCountry || currentNode.birthCountry;
      const excludeNames = currentLives.map(l => l.name);

      const results = await findPreviousLifeCandidates(targetDate, locationConstraint, excludeNames);

      if (results && results.length > 0) {
        setCandidates(results);
      } else {
        setError("The threads of history fade into obscurity here. No further records could be found.");
      }
    } catch (err) {
      console.error(err);
      setError("The cosmic archives are currently unreachable. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleSelectCandidate = async (candidate: GeminiPersonResponse) => {
    // Get historical events from local fallback immediately
    const birthYear = candidate.birthDate.split('-')[0];
    const deathYear = candidate.deathDate === 'Present' ? new Date().getFullYear().toString() : candidate.deathDate.split('-')[0];
    const events = await getHistoricalEvents(birthYear, deathYear, candidate.deathCountry);

    const newNode: LifeNode = {
      id: `life-${Date.now()}`,
      name: candidate.name,
      birthDate: candidate.birthDate,
      birthCountry: candidate.birthCountry,
      deathDate: candidate.deathDate,
      deathPlace: candidate.deathPlace,
      deathCountry: candidate.deathCountry,
      description: candidate.description,
      wikipediaUrl: `https://en.wikipedia.org/wiki/${encodeURIComponent(candidate.wikipediaQuery)}`,
      isUser: false,
      historicalEvents: events
    };

    const newLives = [...lives, newNode];
    setLives(newLives);
    setCandidates([]); // Clear selection

    // Fetch next candidates
    await fetchCandidatesForNode(newNode, newLives);
  };

  const handleShuffle = () => {
    if (lives.length > 0) {
      const lastLife = lives[lives.length - 1];
      fetchCandidatesForNode(lastLife, lives);
    }
  };

  // Hard Reset - Back to Input Form, clears everything
  const handleFullReset = () => {
    setLives([]);
    setCandidates([]);
    setError(null);
    setLoading(false);
    setInitialParams(null);
  };

  // Restart - Resets tree but keeps input params
  const handleRestart = () => {
    if (initialParams) {
        startChain(initialParams);
    }
  };

  // Determine if bubbles should stop appearing
  // Stop if candidates are found OR if there is an error
  const areCandidatesReady = candidates.length > 0 || error !== null;

  return (
    <div className="min-h-screen bg-mystic-950 text-mystic-50 font-sans selection:bg-mystic-500 selection:text-white pb-20 overflow-x-hidden">
      {/* Header */}
      <header className="p-6 border-b border-mystic-800 bg-mystic-950/80 backdrop-blur sticky top-0 z-50">
        <div className="max-w-6xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="bg-mystic-800 p-2 rounded-full border border-mystic-600">
                <History className="w-6 h-6 text-mystic-300" />
             </div>
             <h1 className="text-2xl font-serif font-bold tracking-wide text-white">My Previous Lives</h1>
          </div>
          {lives.length > 0 && (
            <button 
              onClick={handleFullReset}
              className="flex items-center gap-2 text-sm text-mystic-400 hover:text-white transition-colors"
            >
              <RotateCcw className="w-4 h-4" /> New Search
            </button>
          )}
        </div>
      </header>

      {/* Main Content */}
      <main className="container mx-auto px-4 pt-12 flex flex-col items-center">
        {lives.length === 0 ? (
          <div className="max-w-xl w-full mx-auto mt-10">
            <InputForm onSubmit={startChain} isLoading={loading} />

            <div className="mt-12 text-center text-mystic-400 text-sm">
              <p className="font-serif italic opacity-70">
                "Life is a tapestry woven by the threads of time."
              </p>
            </div>
          </div>
        ) : (
          <div className="relative w-full max-w-4xl">
             <Timeline lives={lives} candidatesReady={areCandidatesReady} />

             {/* The Selection Area appears at the end of the timeline */}
             <div className="mt-4 mb-8">
                {(loading || candidates.length > 0 || error) && (
                   <SelectionArea 
                      candidates={candidates}
                      isLoading={loading}
                      onSelect={handleSelectCandidate}
                      onShuffle={handleShuffle}
                   />
                )}
             </div>

             {/* Error Message */}
             {error && !loading && candidates.length === 0 && (
                <div className="max-w-lg mx-auto mt-8 p-4 bg-red-900/30 border border-red-800/50 rounded-lg text-red-200 text-center animate-fade-in-up">
                    <p>{error}</p>
                    <button 
                        onClick={handleShuffle}
                        className="mt-2 text-sm underline hover:text-white"
                    >
                        Try connecting again
                    </button>
                </div>
             )}

             {/* Restart Button - The Lowest Button */}
             {initialParams && !loading && (
                <div className="flex justify-center mt-12 animate-fade-in-up">
                    <button
                        onClick={handleRestart}
                        className="flex items-center gap-2 px-6 py-3 bg-mystic-900 border border-mystic-700 rounded-full text-mystic-300 hover:bg-mystic-800 hover:text-white hover:border-mystic-500 transition-all shadow-lg text-sm font-serif tracking-wider"
                    >
                        <RefreshCw className="w-4 h-4" />
                        Restart This Lineage
                    </button>
                </div>
             )}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";
import { GeminiPersonResponse } from "../types";
import { getFallbackEvents } from "../data/fallbackData";

const apiKey = process.env.API_KEY;

if (!apiKey) {
  console.error("API_KEY is not defined in the environment variables.");
}

const ai = new GoogleGenAI({ apiKey: apiKey || "" });

// Use the fastest model available for quick interactions
const MODEL_FASTEST = 'gemini-2.5-flash-latest'; 

// Retry helper with aggressive timing for speed
async function retryOperation<T>(operation: () => Promise<T>, retries = 2, delay = 500): Promise<T> {
  try {
    return await operation();
  } catch (error) {
    if (retries <= 0) throw error;
    console.warn(`Retrying operation... Attempts left: ${retries}. Error:`, error);
    await new Promise(r => setTimeout(r, delay));
    return retryOperation(operation, retries - 1, delay * 1.5);
  }
}

/**
 * Finds historical figures who died on a specific date (or the day before)
 * prioritizing the given country, then continent, then world.
 */
export const findPreviousLifeCandidates = async (
  targetDate: string,
  deathCountry: string,
  excludeNames: string[] = []
): Promise<GeminiPersonResponse[]> => {
  const runQuery = async () => {
    // Simplified prompt for faster token processing
    const prompt = `
      Find 2 famous deceased historical figures who died on ${targetDate}.
      If none found, check day before: ${getDayBefore(targetDate)}.

      Priority: ${deathCountry} > Same Continent > World.
      Exclude: ${excludeNames.join(", ")}.

      Return JSON Array:
      [{
        "name": "Name",
        "birthDate": "YYYY-MM-DD",
        "birthCountry": "Country",
        "deathDate": "YYYY-MM-DD",
        "deathPlace": "City, Country",
        "deathCountry": "Country",
        "description": "1 intriguing sentence.",
        "wikipediaQuery": "Name for Wikipedia Search"
      }]
    `;

    const response = await ai.models.generateContent({
      model: MODEL_FASTEST, // 2.5 Flash is significantly faster than 3-preview
      contents: prompt,
      config: {
        // REMOVED googleSearch tool. It adds 2-5 seconds of latency. 
        // 2.5 Flash has enough internal knowledge for famous figures.
        responseMimeType: "application/json",
      },
    });

    const text = response.text;
    if (!text) return [];

    const jsonStr = text.replace(/```json\n?|\n?```/g, "").trim();

    try {
      const parsed = JSON.parse(jsonStr);
      if (Array.isArray(parsed)) return parsed as GeminiPersonResponse[];
      if (typeof parsed === 'object' && parsed !== null) return [parsed as GeminiPersonResponse];
      return [];
    } catch (e) {
      console.error("JSON parse error", e);
      return [];
    }
  };

  try {
    return await retryOperation(runQuery, 2, 500);
  } catch (error) {
    console.error("Gemini API error in findPreviousLifeCandidates:", error);
    throw error;
  }
};

/**
 * Returns historical events from local database only.
 * No API call, ensuring speed and reliability.
 */
export const getHistoricalEvents = async (
    birthYear: string,
    deathYear: string,
    country: string
): Promise<string[]> => {
    // We treat this as an async function to maintain interface compatibility
    // but it resolves immediately.
    const bYear = parseInt(birthYear);
    if (!isNaN(bYear)) {
        const fallback = getFallbackEvents(bYear);
        // Randomly pick 4 distinct events
        const shuffled = [...fallback].sort(() => 0.5 - Math.random());
        return shuffled.slice(0, 4);
    }
    return getFallbackEvents(1900).slice(0, 4);
}

function getDayBefore(dateStr: string): string {
  const date = new Date(dateStr);
  date.setDate(date.getDate() - 1);
  return date.toISOString().split('T')[0];
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { GeminiPersonResponse } from "../types";
import { getFallbackEvents } from "../data/fallbackData";

const apiKey = process.env.API_KEY;

if (!apiKey) {
  console.error("API_KEY is not defined in the environment variables.");
}

const ai = new GoogleGenAI({ apiKey: apiKey || "" });

const MODEL_FASTEST = 'gemini-2.5-flash-latest'; 

// Define the response schema for zero-latency parsing
const candidateSchema: Schema = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      name: { type: Type.STRING },
      birthDate: { type: Type.STRING },
      birthCountry: { type: Type.STRING },
      deathDate: { type: Type.STRING },
      deathPlace: { type: Type.STRING },
      deathCountry: { type: Type.STRING },
      description: { type: Type.STRING },
      wikipediaQuery: { type: Type.STRING },
    },
    required: ["name", "birthDate", "birthCountry", "deathDate", "deathPlace", "deathCountry", "description", "wikipediaQuery"],
  },
};

/**
 * Finds historical figures who died on a specific date (or the day before)
 * utilizing Schema validation for maximum speed.
 */
export const findPreviousLifeCandidates = async (
  targetDate: string,
  deathCountry: string,
  excludeNames: string[] = []
): Promise<GeminiPersonResponse[]> => {

  // Pre-calculate date to save model inference time
  const dayBefore = getDayBefore(targetDate);

  const prompt = `
    TASK: Return 2 famous historical figures who died on EITHER ${targetDate} OR ${dayBefore}.

    SEARCH PRIORITY:
    1. Died in '${deathCountry}' (Highest Priority)
    2. Died in same Continent
    3. Died Anywhere in World (Global Famous)

    CRITICAL RULES:
    - If no one famous died in '${deathCountry}' on these dates, IMMEDIATELY use Global figures. Do not hesitate.
    - Do NOT include: ${excludeNames.join(", ")}.
    - Descriptions must be exciting but under 20 words.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_FASTEST,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: candidateSchema,
        temperature: 0.3, // Lower temperature for faster, more deterministic retrieval
      },
    });

    // With Schema, we can access the parsed object directly if the SDK supports it,
    // or parse the text which is guaranteed to be valid JSON.
    const text = response.text;
    if (!text) return [];

    const parsed = JSON.parse(text);
    return Array.isArray(parsed) ? parsed : [];

  } catch (error) {
    console.error("Gemini API error:", error);
    // Fail gracefully with empty array so UI handles it
    return [];
  }
};

/**
 * Returns historical events from local database only.
