import Timeline from './components/Timeline';
import SelectionArea from './components/SelectionArea';
import { History, RotateCcw, RefreshCw } from 'lucide-react';

const App: React.FC = () => {
  const [lives, setLives] = useState<LifeNode[]>([]);
  const [candidates, setCandidates] = useState<GeminiPersonResponse[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Store initial params for the "Restart" feature
  const [initialParams, setInitialParams] = useState<SearchParams | null>(null);

  const startChain = async (params: SearchParams) => {
    setLoading(true);
    setError(null);
    setLives([]);
    setCandidates([]);
    setInitialParams(params);

    const userNode: LifeNode = {
      id: 'user',
      name: 'You',
      birthDate: params.date,
      birthCountry: params.country,
      deathDate: 'Present',
      deathPlace: 'Present',
      deathCountry: params.country,
      description: 'The current manifestation of the soul.',
      isUser: true
    };

    setLives([userNode]);

    await fetchCandidatesForNode(userNode, [userNode]);
  };

  const fetchCandidatesForNode = async (
    currentNode: LifeNode, 
    currentLives: LifeNode[],
    extraExclusions: string[] = []
  ) => {
    setLoading(true);
    setError(null);
    setCandidates([]);

    try {
      const targetDate = currentNode.birthDate;
      const locationConstraint = currentNode.deathCountry || currentNode.birthCountry;

      const excludeNames = [...currentLives.map(l => l.name), ...extraExclusions];

      let count = 0;
      await findPreviousLifeCandidates(
        targetDate, 
        locationConstraint, 
        excludeNames,
        (candidate) => {
            // Callback when a candidate is streamed in
            setCandidates(prev => {
                // Prevent duplicates just in case
                if (prev.some(c => c.name === candidate.name)) return prev;
                return [...prev, candidate];
            });
            count++;
        }
      );

      if (count === 0) {
           // If search fails silently, the UI will show empty state or retry
      }

    } catch (err) {
      console.error(err);
      setError("The cosmic archives are currently unreachable. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleSelectCandidate = async (candidate: GeminiPersonResponse) => {
    // Get historical events from local fallback immediately
    const birthYear = candidate.birthDate.split('-')[0];
    const deathYear = candidate.deathDate === 'Present' ? new Date().getFullYear().toString() : candidate.deathDate.split('-')[0];
    const events = await getHistoricalEvents(birthYear, deathYear, candidate.deathCountry);

    const newNode: LifeNode = {
      id: `life-${Date.now()}`,
      name: candidate.name,
      birthDate: candidate.birthDate,
      birthCountry: candidate.birthCountry,
      deathDate: candidate.deathDate,
      deathPlace: candidate.deathPlace,
      deathCountry: candidate.deathCountry,
      description: candidate.description,
      wikipediaUrl: `https://en.wikipedia.org/wiki/${encodeURIComponent(candidate.wikipediaQuery)}`,
      isUser: false,
      historicalEvents: events,
      sources: candidate.sources
    };

    const newLives = [...lives, newNode];
    setLives(newLives);
    setCandidates([]); // Clear selection

    // Fetch next candidates
    await fetchCandidatesForNode(newNode, newLives);
  };

  const handleShuffle = () => {
    if (lives.length > 0) {
      const lastLife = lives[lives.length - 1];
      const currentCandidateNames = candidates.map(c => c.name);
      fetchCandidatesForNode(lastLife, lives, currentCandidateNames);
    }
  };

  const handleFullReset = () => {
    setLives([]);
    setCandidates([]);
    setError(null);
    setLoading(false);
    setInitialParams(null);
  };

  const handleRestart = () => {
    if (initialParams) {
        startChain(initialParams);
    }
  };

  // Stop bubbles if we have results OR if loading is finished (idle)
  const areCandidatesReady = candidates.length > 0 || error !== null;

  return (
    <div className="min-h-screen bg-mystic-950 text-mystic-50 font-sans selection:bg-mystic-500 selection:text-white pb-20 overflow-x-hidden">
      {/* Header */}
      <header className="p-6 border-b border-mystic-800 bg-mystic-950/80 backdrop-blur sticky top-0 z-50">
        <div className="max-w-6xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="bg-mystic-800 p-2 rounded-full border border-mystic-600">
                <History className="w-6 h-6 text-mystic-300" />
             </div>
             <h1 className="text-2xl font-serif font-bold tracking-wide text-white">My Previous Lives</h1>
          </div>
          {lives.length > 0 && (
            <button 
              onClick={handleFullReset}
              className="flex items-center gap-2 text-sm text-mystic-400 hover:text-white transition-colors"
            >
              <RotateCcw className="w-4 h-4" /> New Search
            </button>
          )}
        </div>
      </header>

      {/* Main Content */}
      <main className="container mx-auto px-4 pt-12 flex flex-col items-center">
        {lives.length === 0 ? (
          <div className="max-w-xl w-full mx-auto mt-10">
            <InputForm onSubmit={startChain} isLoading={loading} />

            <div className="mt-12 text-center text-mystic-400 text-sm">
              <p className="font-serif italic opacity-70">
                "Life is a tapestry woven by the threads of time."
              </p>
            </div>
          </div>
        ) : (
          <div className="relative w-full max-w-4xl">
             <Timeline lives={lives} candidatesReady={areCandidatesReady} />

             {/* The Selection Area appears at the end of the timeline */}
             <div className="mt-4 mb-8">
                {/* Show SelectionArea if loading OR we have candidates OR error */}
                {(loading || candidates.length > 0 || error) && (
                   <SelectionArea 
                      candidates={candidates}
                      isLoading={loading && candidates.length === 0} // Only show spinner if NO candidates yet
                      onSelect={handleSelectCandidate}
                      onShuffle={handleShuffle}
                   />
                )}
             </div>

             {/* Error Message */}
             {error && !loading && candidates.length === 0 && (
                <div className="max-w-lg mx-auto mt-8 p-4 bg-red-900/30 border border-red-800/50 rounded-lg text-red-200 text-center animate-fade-in-up">
                    <p>{error}</p>
                    <button 
                        onClick={handleShuffle}
                        className="mt-2 text-sm underline hover:text-white"
                    >
                        Try connecting again
                    </button>
                </div>
             )}

             {/* Restart Button */}
             {initialParams && !loading && (
                <div className="flex justify-center mt-12 animate-fade-in-up">
                    <button
                        onClick={handleRestart}
                        className="flex items-center gap-2 px-6 py-3 bg-mystic-900 border border-mystic-700 rounded-full text-mystic-300 hover:bg-mystic-800 hover:text-white hover:border-mystic-500 transition-all shadow-lg text-sm font-serif tracking-wider"
                    >
                        <RefreshCw className="w-4 h-4" />
                        Restart This Lineage
                    </button>
                </div>
             )}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { GeminiPersonResponse } from "../types";
import { getFallbackEvents } from "../data/fallbackData";

const apiKey = process.env.API_KEY;

if (!apiKey) {
  console.error("API_KEY is not defined in the environment variables.");
}

const ai = new GoogleGenAI({ apiKey: apiKey || "" });

// Using Flash with Search for speed + accuracy.
const MODEL = 'gemini-3-flash-preview'; 

/**
 * Finds historical figures who died on a specific date using Google Search.
 * Uses streaming to return candidates as they are generated.
 */
export const findPreviousLifeCandidates = async (
  targetDate: string,
  deathCountry: string,
  excludeNames: string[],
  onCandidateFound: (candidate: GeminiPersonResponse) => void
): Promise<void> => {

  const prompt = `
    TASK: Find 2 famous historical figures who died on ${targetDate}.

    INSTRUCTIONS:
    1. USE GOOGLE SEARCH to find people who died on exactly ${targetDate}.
    2. Primary source: Wikipedia.
    3. SEARCH QUERY: "famous people died on ${targetDate} site:wikipedia.org"
    4. If no exact matches are found for the specific day, look for people who died in the same MONTH and YEAR in ${deathCountry} or globally.
    5. Fallback: If search fails completely, use your internal knowledge to estimate.

    OUTPUT FORMAT:
    Return a strictly valid JSON ARRAY of objects.
    Do not use markdown code blocks. Just the raw JSON or [ ... ].

    JSON Structure per item:
    {
      "name": "Name",
      "birthDate": "YYYY-MM-DD",
      "birthCountry": "Country",
      "deathDate": "YYYY-MM-DD",
      "deathPlace": "City, Country",
      "deathCountry": "Country",
      "description": "Exciting description under 15 words.",
      "wikipediaQuery": "Name of Person"
    }

    EXCLUSIONS: Do not include ${excludeNames.join(", ")}.
  `;

  try {
    const result = await ai.models.generateContentStream({
      model: MODEL,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json", // Hint for JSON output even with tools
      },
    });

    let buffer = "";
    let depth = 0;
    let objStartIndex = -1;
    let collectedSources: { title: string, url: string }[] = [];

    // FIXED: Iterate result directly. The SDK returns an async iterable response.
    for await (const chunk of result) {
      // Capture grounding metadata if available
      if (chunk.groundingMetadata?.groundingChunks) {
        chunk.groundingMetadata.groundingChunks.forEach(c => {
          if (c.web?.uri && c.web?.title) {
            collectedSources.push({ title: c.web.title, url: c.web.uri });
          }
        });
      }

      const text = chunk.text;
      if (!text) continue;

      buffer += text;

      // Robust JSON extraction from stream
      // We look for complete objects { ... } inside the array [ ... ]
      let scanIndex = 0;
      while (scanIndex < buffer.length) {
        const char = buffer[scanIndex];

        if (char === '{') {
          if (depth === 0) {
            objStartIndex = scanIndex;
          }
          depth++;
        } else if (char === '}') {
          depth--;
          if (depth === 0 && objStartIndex !== -1) {
            // Potential complete object
            const jsonStr = buffer.substring(objStartIndex, scanIndex + 1);
            try {
              const candidate = JSON.parse(jsonStr);
              if (candidate.name && candidate.description) {
                // Attach sources to the candidate
                candidate.sources = [...collectedSources]; 
                onCandidateFound(candidate);

                // We keep searching for more objects in the stream
                objStartIndex = -1;
              }
            } catch (e) {
              // Not valid JSON yet
            }
          }
        }
        scanIndex++;
      }
    }

  } catch (error) {
    console.error("Gemini API error:", error);
    // Silent fail in stream, UI handles timeout/empty state
  }
};

/**
 * Returns historical events from local database only.
 */
export const getHistoricalEvents = async (
    birthYear: string,
    deathYear: string,
    country: string
): Promise<string[]> => {
    const bYear = parseInt(birthYear);
    if (!isNaN(bYear)) {
        const fallback = getFallbackEvents(bYear);
        const shuffled = [...fallback].sort(() => 0.5 - Math.random());
        return shuffled.slice(0, 4);
    }
    return getFallbackEvents(1900).slice(0, 4);
}

