import React, { useEffect, useState, useMemo } from 'react';
import { LifeNode } from '../types';
import { MapPin, Calendar, ExternalLink, Skull, BookOpen } from 'lucide-react';

interface LifeCardProps {
  life: LifeNode;
  index: number;
  isLast: boolean;
  stopBubbles: boolean; // Signal to stop showing new bubbles
}

// Definition of 6 distinct zones around the card (3 left, 3 right)
// We add "isLeft" to help with connector line logic
const ZONES = [
  // LEFT SIDE
  { class: "md:top-[-2rem] md:left-[-18rem] origin-bottom-right", isLeft: true }, // Top Left
  { class: "md:top-1/2 md:-translate-y-1/2 md:left-[-23rem] origin-right", isLeft: true }, // Mid Left
  { class: "md:bottom-[-2rem] md:left-[-18rem] origin-top-right", isLeft: true }, // Bottom Left

  // RIGHT SIDE
  { class: "md:top-[-2rem] md:right-[-18rem] origin-bottom-left", isLeft: false }, // Top Right
  { class: "md:top-1/2 md:-translate-y-1/2 md:right-[-23rem] origin-left", isLeft: false }, // Mid Right
  { class: "md:bottom-[-2rem] md:right-[-18rem] origin-top-left", isLeft: false }, // Bottom Right
];

const LifeCard: React.FC<LifeCardProps> = ({ life, index, isLast, stopBubbles }) => {
  const [visibleBubbles, setVisibleBubbles] = useState<number>(0);

  // Shuffle positions once on mount (or useMemo with life.id to be deterministic but random-looking)
  // This satisfies "open them in random places around the character card"
  const randomizedZones = useMemo(() => {
    // Clone and shuffle
    return [...ZONES].sort(() => Math.random() - 0.5);
  }, [life.id]);

  // Stagger animation delay based on index for the main card
  const animationDelay = `${index * 0.2}s`;

  // Logic to show bubbles one by one
  useEffect(() => {
    if (!isLast || !life.historicalEvents) return;

    // Reset if it's a new life node (re-mount)
    setVisibleBubbles(0);

    const interval = setInterval(() => {
        if (stopBubbles) {
            clearInterval(interval);
            return;
        }

        setVisibleBubbles(prev => {
            if (life.historicalEvents && prev < life.historicalEvents.length) {
                return prev + 1;
            }
            clearInterval(interval);
            return prev;
        });
    }, 3500); // New bubble every 3.5 seconds

    return () => clearInterval(interval);
  }, [isLast, stopBubbles, life.historicalEvents]);


  if (life.isUser) {
    return (
      <div 
        className="relative flex flex-col items-center animate-fade-in-up w-full" 
        style={{ animationDelay }}
      >
        <div className="z-10 w-full max-w-2xl bg-gradient-to-br from-mystic-800 to-mystic-900 border-2 border-mystic-500 rounded-xl p-6 shadow-[0_0_30px_rgba(129,84,175,0.2)]">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-xl font-serif font-bold text-white">Your Current Incarnation</h3>
            <span className="px-3 py-1 bg-mystic-700 rounded-full text-xs font-bold text-mystic-200">PRESENT</span>
          </div>
          <div className="flex items-start gap-4">
             {/* Silhouette for User */}
             <div className="w-16 h-16 bg-mystic-700 rounded-full flex items-center justify-center border border-mystic-500 shrink-0 overflow-hidden">
                <svg className="w-12 h-12 text-mystic-400" viewBox="0 0 24 24" fill="currentColor">
                    <path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z" />
                </svg>
             </div>
             <div className="space-y-2 text-mystic-200">
                <div className="flex items-center gap-2">
                <Calendar className="w-4 h-4 text-mystic-400" />
                <span>Born: <span className="text-white font-semibold">{life.birthDate}</span></span>
                </div>
                <div className="flex items-center gap-2">
                <MapPin className="w-4 h-4 text-mystic-400" />
                <span>Place: <span className="text-white font-semibold">{life.birthCountry}</span></span>
                </div>
             </div>
          </div>
        </div>
        {/* Connector Line */}
        <div className="h-12 w-0.5 bg-gradient-to-b from-mystic-500 to-mystic-700 my-2"></div>
      </div>
    );
  }

  return (
    <div 
      className="relative flex flex-col items-center w-full animate-fade-in-up"
      style={{ animationDelay: isLast ? '0s' : animationDelay }} 
    >
      <div className="relative z-10 w-full max-w-2xl my-6 md:my-0">

          {/* Historical Event Balloons */}
          {life.historicalEvents && life.historicalEvents.map((event, i) => {
             // Calculate if this specific event is currently visible.
             // We show an event if it's within the window of the last 6 generated bubbles.
             // e.g., if visibleBubbles is 7, we show events 1, 2, 3, 4, 5, 6. Event 0 is hidden.
             const isVisible = i < visibleBubbles && i >= visibleBubbles - 6;

             // Map index to one of the 6 zones cyclically
             const zone = randomizedZones[i % randomizedZones.length];

             return (
                 <div 
                    key={i}
                    className={`
                        absolute z-0 flex items-center w-40 md:w-52
                        text-center justify-center
                        transition-all duration-700 ease-out
                        ${zone.class}
                        ${isVisible ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-90 translate-y-4 pointer-events-none'}
                        /* Mobile Positioning override: just stack them roughly */
                        max-md:!static max-md:w-full max-md:my-2 max-md:translate-y-0 max-md:opacity-100
                        max-md:scale-100 max-md:origin-center
                        ${!isVisible ? 'max-md:hidden' : ''} /* Hide old events on mobile too to prevent huge stacks */
                    `}
                 >
                    {/* Connector Line (Desktop Only) */}
                    <div className={`
                        hidden md:block absolute top-1/2 w-12 h-px bg-mystic-500/50
                        ${zone.isLeft ? '-right-12' : '-left-12'}
                    `}></div>

                    <div className="bg-mystic-900/90 backdrop-blur-md border border-mystic-500 p-3 md:p-4 rounded-xl shadow-2xl text-xs font-serif text-mystic-200 leading-snug text-center w-full">
                        {event}
                    </div>
                 </div>
             );
          })}

          {/* Main Card */}
          <div className="relative z-10 bg-parchment text-gray-900 rounded-xl overflow-hidden shadow-2xl border border-mystic-300">
            <div className="bg-mystic-100 p-4 border-b border-mystic-200 flex justify-between items-start">
                <div className="flex gap-4">
                    {/* Portrait Placeholder */}
                    <div className="w-16 h-16 bg-gray-300 rounded-lg border-2 border-white shadow-sm flex items-center justify-center shrink-0 overflow-hidden">
                        <svg className="w-12 h-12 text-gray-400 translate-y-2" viewBox="0 0 24 24" fill="currentColor">
                            <path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z" />
                        </svg>
                    </div>
                    <div>
                        <h3 className="text-2xl font-serif font-bold text-mystic-900 leading-tight">{life.name}</h3>
                        <div className="flex items-center gap-2 text-mystic-800 text-sm mt-1">
                            <MapPin className="w-3 h-3" />
                            <span>{life.birthCountry}</span>
                        </div>
                    </div>
                </div>
                {life.wikipediaUrl && (
                    <a 
                        href={life.wikipediaUrl} 
                        target="_blank" 
                        rel="noopener noreferrer"
                        className="text-mystic-600 hover:text-mystic-800 transition-colors"
                        title="Read on Wikipedia"
                    >
                        <ExternalLink className="w-5 h-5" />
                    </a>
                )}
            </div>

            <div className="p-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-4">
                    <div className="bg-white/50 p-3 rounded-lg border border-mystic-200">
                        <div className="flex items-center gap-2 text-mystic-700 mb-1 font-bold text-xs uppercase tracking-wider">
                            <Calendar className="w-3 h-3" /> Birth
                        </div>
                        <div className="font-serif text-lg">{life.birthDate}</div>
                        <div className="text-sm text-gray-600">{life.birthCountry}</div>
                    </div>
                    <div className="bg-mystic-50/50 p-3 rounded-lg border border-mystic-200">
                        <div className="flex items-center gap-2 text-red-800 mb-1 font-bold text-xs uppercase tracking-wider">
                            <Skull className="w-3 h-3" /> Death
                        </div>
                        <div className="font-serif text-lg">{life.deathDate}</div>
                        <div className="text-sm text-gray-600">{life.deathPlace}</div>
                    </div>
                </div>

                <p className="text-gray-700 font-serif leading-relaxed italic border-l-4 border-mystic-400 pl-4 py-1">
                    "{life.description}"
                </p>

                {/* Sources Section if available */}
                {life.sources && life.sources.length > 0 && (
                   <div className="mt-4 pt-2 border-t border-mystic-200">
                      <div className="flex items-center gap-1 text-xs text-mystic-600 mb-1">
                         <BookOpen className="w-3 h-3" /> Sources
                      </div>
                      <div className="flex flex-wrap gap-2">
                        {life.sources.slice(0, 2).map((src, idx) => (
                           <a 
                             key={idx} 
                             href={src.url} 
                             target="_blank" 
                             rel="noopener noreferrer"
                             className="text-[10px] text-blue-600 hover:underline truncate max-w-[200px]"
                           >
                             {src.title}
                           </a>
                        ))}
                      </div>
                   </div>
                )}

                <div className="mt-4 pt-4 border-t border-gray-200 text-xs text-gray-500 text-center">
                    Reincarnated as next soul on {life.deathDate}
                </div>
            </div>
          </div>
      </div>

      {/* Connection Logic */}
      <div className="h-12 w-0.5 bg-gradient-to-b from-mystic-700 to-mystic-500 my-2"></div>
    </div>
  );
};

