                    <svg className="w-12 h-12 text-mystic-400" viewBox="0 0 24 24" fill="currentColor">
                        <path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z" />
                    </svg>
                </div>
                <div className="space-y-2 text-mystic-200">
                    <div className="flex items-center gap-2">
                        <Calendar className="w-4 h-4 text-mystic-400" />
                        <span>Born: <span className="text-white font-semibold">{life.birthDate}</span></span>
                    </div>
                    <div className="flex items-center gap-2">
                        <MapPin className="w-4 h-4 text-mystic-400" />
                        <span className="flex items-center gap-2">
