import { GoogleGenAI } from "@google/genai";
import { GeminiPersonResponse } from "../types";
import { getFallbackEvents } from "../data/fallbackData";

const apiKey = process.env.API_KEY;

if (!apiKey) {
  console.error("API_KEY is not defined in the environment variables.");
}

const ai = new GoogleGenAI({ apiKey: apiKey || "" });

// Using Flash for speed.
const MODEL = 'gemini-3-flash-preview'; 

// Simple in-memory cache for event details to save API calls
const eventCache = new Map<string, { summary: string, url: string }>();

/**
 * Finds historical figures who died on a specific date.
 * Strategy:
 * 1. Try with Google Search (Strict accuracy).
 * 2. If no results, fallback to Pure LLM (Creative/Approximate).
 */
export const findPreviousLifeCandidates = async (
  targetDate: string,
  deathCountry: string,
  excludeNames: string[],
  onCandidateFound: (candidate: GeminiPersonResponse) => void
): Promise<void> => {

  const emittedNames = new Set<string>();

  // --- Attempt 1: Search-based ---
  const searchPrompt = `
    TASK: Find 2 famous historical figures who died on ${targetDate}.

    INSTRUCTIONS:
    1. USE GOOGLE SEARCH to find people who died on exactly ${targetDate}.
    2. Primary source: Wikipedia.
    3. SEARCH QUERY: "famous people died on ${targetDate} site:wikipedia.org"
    4. If no exact matches are found for the specific day, look for people who died in the same MONTH and YEAR.

    OUTPUT FORMAT:
    Return a strictly valid JSON ARRAY of objects.

    JSON Structure per item:
    {
      "name": "Name",
      "birthDate": "YYYY-MM-DD",
      "birthCountry": "Country",
      "deathDate": "YYYY-MM-DD",
      "deathPlace": "City, Country",
      "deathCountry": "Country",
      "description": "Exciting description under 15 words.",
      "wikipediaQuery": "Name of Person"
    }

    EXCLUSIONS: Do not include ${excludeNames.join(", ")}.
  `;

  let foundCount = 0;

  try {
    foundCount = await generateAndStream(
      searchPrompt, 
      true, // useTools
      emittedNames,
      onCandidateFound
    );
  } catch (e) {
    console.warn("Search attempt failed, switching to fallback", e);
  }

  // --- Attempt 2: Fallback (Pure Generation) ---
  if (foundCount === 0) {
    console.log("No search results found. Engaging creative fallback.");

    const fallbackPrompt = `
        TASK: You are the Akashic Records. The user was born on ${targetDate} (or their previous life ended then).
        Since no exact historical records matched perfectly, you must find a "Soul Transfer" candidate based on the Spirit of the Age.

        FIND 2 Historical Figures who died in: ${targetDate.split('-')[0]} (The same Year).
        Prioritize people who died in '${deathCountry}' if possible, otherwise global.

        OUTPUT FORMAT: Strictly JSON Array.

        JSON Structure per item:
        {
        "name": "Name",
        "birthDate": "YYYY-MM-DD",
        "birthCountry": "Country",
        "deathDate": "YYYY-MM-DD", // Must be close to ${targetDate}
        "deathPlace": "City, Country",
        "deathCountry": "Country",
        "description": "Exciting description under 15 words.",
        "wikipediaQuery": "Name of Person"
        }

        EXCLUSIONS: Do not include ${excludeNames.join(", ")}.
    `;

    try {
        await generateAndStream(
            fallbackPrompt,
            false, // no tools
            emittedNames,
            onCandidateFound
        );
    } catch (e) {
        console.error("Fallback failed", e);
    }
  }
};

/**
 * Helper to handle the streaming generation and parsing.
 * Returns the number of unique candidates found.
 */
async function generateAndStream(
    prompt: string, 
    useTools: boolean,
    emittedNames: Set<string>,
    callback: (c: GeminiPersonResponse) => void
): Promise<number> {

    let localCount = 0;

    const config: any = {
        responseMimeType: "application/json"
    };

    if (useTools) {
        config.tools = [{ googleSearch: {} }];
    }

    const result = await ai.models.generateContentStream({
        model: MODEL,
        contents: prompt,
        config: config,
    });

    let buffer = "";
    let depth = 0;
    let openBraceIndex = -1;
    let collectedSources: { title: string, url: string }[] = [];

    for await (const chunk of result) {
        // Collect sources if available (Grounding)
        const candidate = chunk.candidates?.[0];
        if (candidate?.groundingMetadata?.groundingChunks) {
            candidate.groundingMetadata.groundingChunks.forEach(c => {
                if (c.web?.uri && c.web?.title) {
                    collectedSources.push({ title: c.web.title, url: c.web.uri });
                }
            });
        }

        const text = chunk.text;
        if (!text) continue;

        // Append text to buffer
        buffer += text;

        // Scan buffer for complete objects
        let scanIndex = 0;
        depth = 0;
        openBraceIndex = -1;

        while (scanIndex < buffer.length) {
            const char = buffer[scanIndex];

            if (char === '{') {
                if (depth === 0) openBraceIndex = scanIndex;
                depth++;
            } else if (char === '}') {
                depth--;
                if (depth === 0 && openBraceIndex !== -1) {
                    const jsonStr = buffer.substring(openBraceIndex, scanIndex + 1);
                    try {
                        const candidate = JSON.parse(jsonStr);
                        if (candidate.name && candidate.description) {
                            if (!emittedNames.has(candidate.name)) {
                                emittedNames.add(candidate.name);

                                // Attach sources if using tools
                                if (useTools && collectedSources.length > 0) {
                                    candidate.sources = [...collectedSources];
                                }

                                callback(candidate);
                                localCount++;
                            }
                        }
                    } catch (e) {
                        // Incomplete or invalid
                    }
                    openBraceIndex = -1;
                }
            }
            scanIndex++;
        }
    }
    return localCount;
}

/**
 * Returns historical events from local database only.
 * Sorts them by Year (Descending) to show most recent first.
 */
export const getHistoricalEvents = async (
    birthYear: string,
    deathYear: string,
    country: string
): Promise<string[]> => {
    const bYear = parseInt(birthYear);
    if (!isNaN(bYear)) {
        let events = getFallbackEvents(bYear);

        // Sort descending by year (Most recent first)
        // Extracts year from string like "Event Name (1989)"
        events = events.sort((a, b) => {
            const yearA = parseInt(a.match(/\((\d{4})\)/)?.[1] || "0");
            const yearB = parseInt(b.match(/\((\d{4})\)/)?.[1] || "0");
            return yearB - yearA;
        });

        // Take top 24 most recent to allow cycling through events
        return events.slice(0, 24);
    }
    return getFallbackEvents(1900).slice(0, 24);
}

/**
 * Fetches a summary and Wikipedia URL for a specific historical event.
 */
export const getEventDetails = async (eventName: string): Promise<{ summary: string, url: string } | null> => {
  // Check Cache First
  if (eventCache.has(eventName)) {
    return eventCache.get(eventName) || null;
  }

  const prompt = `
    TASK: Provide a concise summary (max 30 words) and a valid Wikipedia URL for the historical event: "${eventName}".
    If the event text is ambiguous, use the year in the text to disambiguate.

    OUTPUT JSON:
    {
      "summary": "...",
      "url": "..."
    }
  `;

  try {
    const response = await ai.models.generateContent({
        model: MODEL,
        contents: prompt,
        config: { responseMimeType: "application/json" }
    });

    if (response.text) {
        // Robust cleaning: remove markdown blocks if present
        let cleanText = response.text.replace(/```json\s*|\s*```/g, "").replace(/```/g, "").trim();

        try {
            const data = JSON.parse(cleanText);
            // Cache success response
            if (data.summary && data.url) {
                eventCache.set(eventName, data);
            }
            return data;
        } catch (parseError) {
             console.warn("Failed to parse event details JSON:", cleanText);
             return null;
        }
    }
    return null;
  } catch (e) {
    console.error("Error fetching event details", e);
    return null;
  }
};

import React, { useState } from 'react';
import { SearchParams } from '../types';
import { Sparkles } from 'lucide-react';

interface InputFormProps {
  onSubmit: (params: SearchParams) => void;
  isLoading: boolean;
}

const InputForm: React.FC<InputFormProps> = ({ onSubmit, isLoading }) => {
  // We use separate states for flexible input handling
  const [day, setDay] = useState('');
  const [month, setMonth] = useState('');
  const [year, setYear] = useState('');
  const [country, setCountry] = useState('');
  const [validationError, setValidationError] = useState<string | null>(null);

  // Validate date logic
  const isValidDate = (d: string, m: string, y: string) => {
    const dayNum = parseInt(d, 10);
    const monthNum = parseInt(m, 10);
    const yearNum = parseInt(y, 10);

    if (isNaN(dayNum) || isNaN(monthNum) || isNaN(yearNum)) return false;

    // Basic range checks
    if (yearNum < 1000 || yearNum > new Date().getFullYear()) return false;
    if (monthNum < 1 || monthNum > 12) return false;
    if (dayNum < 1 || dayNum > 31) return false;

    // JS Date object check (handles leap years etc.)
    const date = new Date(yearNum, monthNum - 1, dayNum);
    return (
      date.getFullYear() === yearNum &&
      date.getMonth() === monthNum - 1 &&
      date.getDate() === dayNum
    );
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setValidationError(null);

    // Sanitize
    const cleanCountry = country.trim();

    if (!isValidDate(day, month, year)) {
      setValidationError("Please enter a valid historical date.");
      return;
    }

    if (!cleanCountry) {
        setValidationError("Please enter a birth country.");
        return;
    }

    const dateStr = `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
    onSubmit({ date: dateStr, country: cleanCountry });
  };

  // Year handling logic
  const handleYearKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (/^[0-9]$/.test(e.key)) {
      if (year.length === 4) {
        const target = e.target as HTMLInputElement;
        if (target.selectionStart === target.selectionEnd) {
          e.preventDefault();
          setYear(e.key);
        }
      }
    }
  };

  const handleYearChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value.replace(/\D/g, '');
      if (val.length <= 4) {
          setYear(val);
      }
  };

  const handleDayChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      let val = e.target.value.replace(/\D/g, '');
      if (val.length > 2) val = val.slice(0, 2);
      setDay(val);
  };

  const handleDayBlur = () => {
      if (day.length === 1) setDay(day.padStart(2, '0'));
  };

  // Month options
  const months = [
    { value: '01', label: 'January' },
    { value: '02', label: 'February' },
    { value: '03', label: 'March' },
    { value: '04', label: 'April' },
    { value: '05', label: 'May' },
    { value: '06', label: 'June' },
    { value: '07', label: 'July' },
    { value: '08', label: 'August' },
    { value: '09', label: 'September' },
    { value: '10', label: 'October' },
    { value: '11', label: 'November' },
    { value: '12', label: 'December' },
  ];

  return (
    <div className="max-w-md mx-auto bg-mystic-900/40 backdrop-blur-xl p-8 rounded-2xl border border-mystic-500/30 shadow-[0_0_50px_rgba(0,0,0,0.5)] animate-fade-in-up relative overflow-hidden group">
      {/* Decorative gradient orb */}
      <div className="absolute -top-20 -right-20 w-40 h-40 bg-purple-500/10 rounded-full blur-3xl group-hover:bg-purple-500/20 transition-colors duration-1000"></div>

      <div className="text-center mb-8 relative z-10">
        <div className="inline-block p-4 rounded-full bg-gradient-to-br from-mystic-800 to-mystic-950 border border-mystic-600/50 mb-4 shadow-[0_0_20px_rgba(139,92,246,0.2)]">
          <Sparkles className="w-8 h-8 text-yellow-300 animate-pulse-slow drop-shadow-[0_0_8px_rgba(253,224,71,0.5)]" />
        </div>
        <h2 className="text-3xl font-serif font-bold text-white tracking-wide">Enter Your Origin</h2>
        <p className="text-mystic-300 mt-3 text-sm font-light tracking-wide">The thread of history begins with you.</p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6 relative z-10" noValidate>
        <div>
          <label className="block text-xs font-bold text-mystic-300 mb-2 uppercase tracking-widest pl-1">
            Date of Birth
          </label>
          <div className="grid grid-cols-3 gap-3">

            {/* Year Input */}
            <input 
                type="text"
                inputMode="numeric"
                value={year}
                onChange={handleYearChange}
                onKeyDown={handleYearKeyDown}
                placeholder="Year"
                required
                aria-label="Year of Birth"
                className="w-full px-4 py-3 bg-mystic-950/60 border border-mystic-700/50 rounded-xl focus:ring-2 focus:ring-mystic-500/50 focus:border-mystic-500/50 text-white placeholder-mystic-600 outline-none transition-all text-center backdrop-blur-sm"
            />

            {/* Month Select */}
            <div className="relative col-span-1">
                <select
                    value={month}
                    onChange={(e) => setMonth(e.target.value)}
                    required
                    aria-label="Month of Birth"
                    className="w-full appearance-none px-4 py-3 bg-mystic-950/60 border border-mystic-700/50 rounded-xl focus:ring-2 focus:ring-mystic-500/50 focus:border-mystic-500/50 text-white outline-none transition-all cursor-pointer backdrop-blur-sm text-center"
                >
                    <option value="" disabled>Month</option>
                    {months.map(m => (
                        <option key={m.value} value={m.value}>{m.label.substring(0, 3)}</option>
                    ))}
                </select>
            </div>

            {/* Day Input */}
            <input 
                type="text"
                inputMode="numeric"
                value={day}
                onChange={handleDayChange}
                onBlur={handleDayBlur}
                placeholder="Day"
                required
                aria-label="Day of Birth"
                className="w-full px-4 py-3 bg-mystic-950/60 border border-mystic-700/50 rounded-xl focus:ring-2 focus:ring-mystic-500/50 focus:border-mystic-500/50 text-white placeholder-mystic-600 outline-none transition-all text-center backdrop-blur-sm"
            />

          </div>
        </div>

        <div>
          <label htmlFor="country" className="block text-xs font-bold text-mystic-300 mb-2 uppercase tracking-widest pl-1">
            Country of Birth
          </label>
          <input
            id="country"
            type="text"
            required
            placeholder="e.g., France, Japan, Brazil"
            value={country}
            onChange={(e) => setCountry(e.target.value)}
            className="w-full px-4 py-3 bg-mystic-950/60 border border-mystic-700/50 rounded-xl focus:ring-2 focus:ring-mystic-500/50 focus:border-mystic-500/50 text-white outline-none transition-all placeholder-mystic-700 backdrop-blur-sm"
          />
        </div>

        {validationError && (
            <div className="text-red-300 text-sm text-center bg-red-900/30 p-2 rounded-lg border border-red-800/50" role="alert">
                {validationError}
            </div>
        )}

        <button
          type="submit"
          disabled={isLoading || !day || !month || !year || year.length < 4}
          className={`w-full py-4 px-6 rounded-xl font-serif font-bold text-lg tracking-wide shadow-lg transition-all transform duration-300
            ${isLoading || !day || !month || !year || year.length < 4
              ? 'bg-mystic-800/50 text-mystic-500 cursor-not-allowed border border-mystic-800/50' 
              : 'bg-gradient-to-r from-violet-700 to-fuchsia-800 text-white hover:from-violet-600 hover:to-fuchsia-700 border border-white/10 hover:shadow-[0_0_25px_rgba(167,139,250,0.4)] hover:-translate-y-1'
            }`}
        >
          {isLoading ? (
             <span className="flex items-center justify-center gap-2">
                 <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
                 Consulting...
             </span>
          ) : 'Reveal My Past Lives'}
        </button>
      </form>
    </div>
  );
};

