                            rel="noopener noreferrer"
                            className="text-xs text-mystic-400 hover:text-yellow-400 transition-colors flex items-center justify-center gap-1 focus:outline-none focus:underline"
                        >
                            Open in Google Maps <ExternalLink className="w-3 h-3" />
                        </a>
                    </div>
                </div>
            </div>
        )}
      </>
    );
  }

  return (
    <>
      <div 
        className="relative flex flex-col items-center w-full animate-fade-in-up"
        style={{ animationDelay: isLast ? '0s' : animationDelay }} 
      >
        <div className="relative z-10 w-full max-w-2xl my-6 md:my-0">

