                              <span className="flex items-center gap-1">
                                {life.birthCountry}
                                <button
                                    onClick={() => setShowMap(true)}
                                    className="ml-1 p-0.5 text-mystic-600 hover:text-mystic-900 hover:bg-mystic-200/50 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-mystic-400"
                                    title="View on Map"
                                    aria-label={`View map of ${life.birthCountry}`}
                                >
                                    <Globe className="w-3 h-3" />
                                </button>
                              </span>
