                >
                    <X className="w-5 h-5" />
                </button>

                <h3 id="event-modal-title" className="text-xl font-serif font-bold text-white mb-6 pr-8 border-b border-mystic-700 pb-2">{selectedEvent}</h3>

                {loadingDetails ? (
                    <div className="flex flex-col items-center py-8 gap-4">
                         <div className="w-8 h-8 border-2 border-mystic-400 border-t-transparent rounded-full animate-spin"></div>
