import React, { Component, ErrorInfo, ReactNode } from 'react';
import { RefreshCw, AlertTriangle } from 'lucide-react';

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null,
  };

  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Uncaught error:', error, errorInfo);
  }

  public render() {
    if (this.state.hasError) {
      if (this.props.fallback) {
        return this.props.fallback;
      }

      return (
        <div className="p-6 bg-red-950/30 border border-red-800/50 rounded-xl text-center backdrop-blur-sm m-4">
          <div className="flex justify-center mb-4">
            <AlertTriangle className="w-10 h-10 text-red-400" />
          </div>
          <h2 className="text-xl font-serif text-red-200 mb-2">A Tear in the Fabric of Time</h2>
          <p className="text-red-300/80 mb-6 text-sm">
            Something went wrong while rendering this part of your history.
          </p>
          <button
            onClick={() => window.location.reload()}
            className="inline-flex items-center gap-2 px-4 py-2 bg-red-900/50 hover:bg-red-800/50 border border-red-700/50 rounded-lg text-red-100 transition-colors"
          >
            <RefreshCw className="w-4 h-4" />
            Reload Application
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;

import React, { useRef, useState, useEffect, ReactNode } from 'react';

interface VirtualItemProps {
  children: ReactNode;
  minHeight?: number;
  buffer?: string; // rootMargin for IntersectionObserver
}

const VirtualItem: React.FC<VirtualItemProps> = ({ 
  children, 
  minHeight = 300, 
  buffer = "600px" // Generous buffer to prevent white flashes while scrolling
}) => {
  const [isVisible, setIsVisible] = useState(false);
  const [height, setHeight] = useState<number | undefined>(undefined);
  const elementRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        } else {
          // When scrolling away, save the height to maintain scroll position
          if (entry.boundingClientRect.height > 0) {
            setHeight(entry.boundingClientRect.height);
          }
          setIsVisible(false);
        }
      },
      {
        rootMargin: buffer,
        threshold: 0
      }
    );

    if (elementRef.current) {
      observer.observe(elementRef.current);
    }

    return () => {
      observer.disconnect();
    };
  }, [buffer]);

  return (
    <div 
      ref={elementRef} 
      style={{ 
        minHeight: height || minHeight,
        // If we have a measured height and it's not visible, enforce strict height
        height: !isVisible && height ? height : 'auto', 
        contain: 'content' // Hints to browser to optimize rendering
      }}
      className="w-full relative"
    >
      {isVisible ? children : null}
    </div>
  );
};

export default VirtualItem;

import React, { useEffect, useState, useMemo, useRef } from 'react';
import { LifeNode } from '../types';
import { MapPin, Calendar, ExternalLink, Skull, BookOpen, X, Info, Globe } from 'lucide-react';
