interface LifeCardProps {
  life: LifeNode;
  index: number;
  isLast: boolean;
  stopBubbles: boolean; // Signal to stop showing new bubbles
}

// Definition of 6 distinct zones around the card (3 left, 3 right)
// We add "isLeft" to help with connector line logic
const ZONES = [
  // LEFT SIDE
  { class: "md:top-[-2rem] md:left-[-18rem] origin-bottom-right", isLeft: true }, // Top Left
  { class: "md:top-1/2 md:-translate-y-1/2 md:left-[-23rem] origin-right", isLeft: true }, // Mid Left
  { class: "md:bottom-[-2rem] md:left-[-18rem] origin-top-right", isLeft: true }, // Bottom Left

  // RIGHT SIDE
  { class: "md:top-[-2rem] md:right-[-18rem] origin-bottom-left", isLeft: false }, // Top Right
  { class: "md:top-1/2 md:-translate-y-1/2 md:right-[-23rem] origin-left", isLeft: false }, // Mid Right
  { class: "md:bottom-[-2rem] md:right-[-18rem] origin-top-left", isLeft: false }, // Bottom Right
];

const LifeCard: React.FC<LifeCardProps> = ({ life, index, isLast, stopBubbles }) => {
  // If it's not the last card, we assume it's "historical" and show all bubbles immediately.
  // This is crucial for virtualization so they don't re-animate when scrolling back up.
  const [visibleBubbles, setVisibleBubbles] = useState<number>(
    isLast ? 0 : (life.historicalEvents?.length || 0)
  );

  // Modal state
  const [selectedEvent, setSelectedEvent] = useState<string | null>(null);
  const [eventDetails, setEventDetails] = useState<{summary: string, url: string} | null>(null);
  const [loadingDetails, setLoadingDetails] = useState(false);
  const eventModalRef = useRef<HTMLDivElement>(null);

  // Map Modal state
  const [showMap, setShowMap] = useState(false);
  const mapModalRef = useRef<HTMLDivElement>(null);

  // Focus management refs
  const lastFocusedElement = useRef<HTMLElement | null>(null);

  // Shuffle positions deterministically based on ID to ensure stability across re-renders/virtualization
  const randomizedZones = useMemo(() => {
    // Simple pseudo-random seeded shuffle using the ID string
    const seed = life.id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
    const zonesCopy = [...ZONES];
    // Fisher-Yates shuffle with seeded randomness
    for (let i = zonesCopy.length - 1; i > 0; i--) {
        const j = (seed + i) % (i + 1);
        [zonesCopy[i], zonesCopy[j]] = [zonesCopy[j], zonesCopy[i]];
    }
    return zonesCopy;
  }, [life.id]);

  // Stagger animation delay based on index for the main card
  // Only apply delay if it's the last card (newly added), otherwise instant for scrolled items
  const animationDelay = isLast ? `${index * 0.2}s` : '0s';

  // Logic to show bubbles one by one
  useEffect(() => {
    // Only animate if it IS the last card and we haven't shown them all yet
    if (!isLast || !life.historicalEvents) {
        // Ensure we show all if state changed to not last
        if (!isLast && life.historicalEvents) {
            setVisibleBubbles(life.historicalEvents.length);
        }
        return;
    }

    // Reset if it's a new life node (re-mount) and we are at 0
    // We don't reset to 0 here to avoid flashing on re-renders, reliance on initial state is better.

    const interval = setInterval(() => {
        if (stopBubbles) {
            clearInterval(interval);
            return;
        }

        setVisibleBubbles(prev => {
            if (life.historicalEvents && prev < life.historicalEvents.length) {
                return prev + 1;
            }
            clearInterval(interval);
            return prev;
        });
    }, 5000); // Slower pacing: New bubble every 5 seconds for readability

    return () => clearInterval(interval);
  }, [isLast, stopBubbles, life.historicalEvents]);

  // Accessibility: Manage focus for Event Modal
  useEffect(() => {
    if (selectedEvent) {
      lastFocusedElement.current = document.activeElement as HTMLElement;
      setTimeout(() => eventModalRef.current?.focus(), 50);
    } else if (lastFocusedElement.current) {
      lastFocusedElement.current.focus();
    }
  }, [selectedEvent]);

  // Accessibility: Manage focus for Map Modal
  useEffect(() => {
    if (showMap) {
      lastFocusedElement.current = document.activeElement as HTMLElement;
      setTimeout(() => mapModalRef.current?.focus(), 50);
    } else if (!showMap && !selectedEvent && lastFocusedElement.current) {
      lastFocusedElement.current.focus();
    }
  }, [showMap]);

  const prefetchEventDetails = (event: string) => {
    getEventDetails(event);
  };

