const CACHE_NAME = 'mpl-v1';
const ASSETS = [
  '/',
  '/index.html',
  'https://cdn.tailwindcss.com',
  'https://fonts.googleapis.com/css2?family=Cinzel:wght@400;700&family=Lato:wght@300;400;700&display=swap'
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      return cache.addAll(ASSETS);
    })
  );
});

self.addEventListener('fetch', (event) => {
  event.respondWith(
    caches.match(event.request).then((response) => {
      return response || fetch(event.request);
    })
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keyList) => {
      return Promise.all(
        keyList.map((key) => {
          if (key !== CACHE_NAME) {
            return caches.delete(key);
          }
        })
      );
    })
  );
});

import { GoogleGenAI, Type } from "@google/genai";
import { GeminiPersonResponse } from "../types";
import { getFallbackEvents } from "../data/fallbackData";

const apiKey = process.env.API_KEY;

if (!apiKey) {
  console.error("API_KEY is not defined in the environment variables.");
}

const ai = new GoogleGenAI({ apiKey: apiKey || "" });

// Using Flash for speed.
const MODEL = 'gemini-3-flash-preview'; 

// Caches
const eventCache = new Map<string, { summary: string, url: string }>();
const candidateCache = new Map<string, GeminiPersonResponse[]>();

/**
 * Finds historical figures who died on a specific date.
 * OPTIMIZED STRATEGY:
 * 1. Check Cache.
 * 2. Single "Best Effort" API call with JSON Schema.
 * 3. Instruct model to fallback to Month/Year matches internally if Day matches aren't found.
 */
export const findPreviousLifeCandidates = async (
  targetDate: string,
  deathCountry: string,
  excludeNames: string[],
  onCandidateFound: (candidate: GeminiPersonResponse) => void
): Promise<void> => {

  // 1. Check Cache
  const cacheKey = `${targetDate}-${deathCountry}`;
  if (candidateCache.has(cacheKey)) {
    const cachedCandidates = candidateCache.get(cacheKey)!;
    // Filter out anyone currently in the chain (excludeNames) to ensure freshness
    // But if we run out of cached items, we might need to fetch again. 
    // For simplicity, we assume the cache is sufficient if it exists.
    const available = cachedCandidates.filter(c => !excludeNames.includes(c.name));

    if (available.length > 0) {
      console.log("Serving candidates from cache");
      available.forEach(c => onCandidateFound(c));
      return;
    }
  }

  // 2. Define Schema
  const candidateSchema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        name: { type: Type.STRING },
        birthDate: { type: Type.STRING, description: "YYYY-MM-DD format" },
        birthCountry: { type: Type.STRING },
        deathDate: { type: Type.STRING, description: "YYYY-MM-DD format" },
        deathPlace: { type: Type.STRING },
        deathCountry: { type: Type.STRING },
        description: { type: Type.STRING, description: "Exciting description under 15 words." },
        wikipediaQuery: { type: Type.STRING, description: "Name to search on Wikipedia" }
      },
      required: ["name", "birthDate", "birthCountry", "deathDate", "deathPlace", "deathCountry", "description", "wikipediaQuery"]
    }
  };

  // 3. Unified Prompt
  const prompt = `
    TASK: Find 2 famous historical figures whose death date connects to the date: ${targetDate}.

    PRIORITY 1: Exact Match. Find people who died on exactly ${targetDate}. Use Google Search with query "site:wikipedia.org died on ${targetDate}" to verify.
    PRIORITY 2: Near Match. If NO exact matches are found (or they are obscure), find people who died in the same MONTH and YEAR (${targetDate.slice(0, 7)}).

    CONTEXT:
    - The user is looking for their "past life".
    - Prioritize figures who died in '${deathCountry}' if available, but Global figures are acceptable.
    - DO NOT include: ${excludeNames.join(", ")}.

    OUTPUT:
    Return a JSON Array obeying the schema.
  `;

  try {
    // We use generateContent (blocking) instead of stream for candidates because 
    // responseSchema works best when the model can validate the entire object.
    // Flash is fast enough that the wait is negligible for 2 items.
    const response = await ai.models.generateContent({
      model: MODEL,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: candidateSchema,
      }
    });

    const jsonText = response.text;
    if (!jsonText) throw new Error("No response text generated");

    const candidates = JSON.parse(jsonText) as GeminiPersonResponse[];

    // Extract sources if available
    const sources: { title: string, url: string }[] = [];
    if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
        response.candidates[0].groundingMetadata.groundingChunks.forEach(c => {
            if (c.web?.uri && c.web?.title) {
                sources.push({ title: c.web.title, url: c.web.uri });
            }
        });
    }

    // Process and Emit
    const validCandidates = candidates.map(c => ({
        ...c,
        sources: sources.length > 0 ? sources : undefined
    }));

    // Update Cache
    if (validCandidates.length > 0) {
        // Append to existing cache or create new
        const existing = candidateCache.get(cacheKey) || [];
        // Unique by name
        const combined = [...existing, ...validCandidates].filter((v, i, a) => a.findIndex(t => t.name === v.name) === i);
        candidateCache.set(cacheKey, combined);
    }

    validCandidates.forEach(c => onCandidateFound(c));

  } catch (e) {
    console.error("Candidate generation failed:", e);
    // Fallback logic could go here, but the "Priority 2" in prompt handles most cases.
  }
};

/**
 * Returns historical events from local database only.
 * Sorts them by Year (Descending) to show most recent first.
 */
export const getHistoricalEvents = async (
    birthYear: string,
    deathYear: string,
    country: string
): Promise<string[]> => {
    const bYear = parseInt(birthYear);
    if (!isNaN(bYear)) {
        let events = getFallbackEvents(bYear);

        // Sort descending by year (Most recent first)
        events = events.sort((a, b) => {
            const yearA = parseInt(a.match(/\((\d{4})\)/)?.[1] || "0");
            const yearB = parseInt(b.match(/\((\d{4})\)/)?.[1] || "0");
            return yearB - yearA;
        });

        return events.slice(0, 24);
    }
    return getFallbackEvents(1900).slice(0, 24);
}

/**
 * Fetches a summary and Wikipedia URL for a specific historical event.
 */
export const getEventDetails = async (eventName: string): Promise<{ summary: string, url: string } | null> => {
  if (eventCache.has(eventName)) {
    return eventCache.get(eventName) || null;
  }

  const prompt = `
    TASK: Provide a concise summary (max 30 words) and a valid Wikipedia URL for the historical event: "${eventName}".
    If the event text is ambiguous, use the year in the text to disambiguate.
  `;

  // Schema for event details
  const eventSchema = {
      type: Type.OBJECT,
      properties: {
          summary: { type: Type.STRING },
          url: { type: Type.STRING }
      },
      required: ["summary", "url"]
  };

  try {
    const response = await ai.models.generateContent({
        model: MODEL,
        contents: prompt,
        config: { 
            responseMimeType: "application/json",
            responseSchema: eventSchema
        }
    });

    if (response.text) {
        try {
            const data = JSON.parse(response.text);
            if (data.summary && data.url) {
                eventCache.set(eventName, data);
            }
            return data;
        } catch (parseError) {
             console.warn("Failed to parse event details JSON:", response.text);
             return null;
        }
    }
    return null;
  } catch (e) {
    console.error("Error fetching event details", e);
    return null;
  }
};

