import { GoogleGenAI, Type } from "@google/genai";
import { GeminiPersonResponse } from "../types";
import { getFallbackEvents } from "../data/fallbackData";

const apiKey = process.env.API_KEY;

if (!apiKey) {
  console.error("API_KEY is not defined in the environment variables.");
}

const ai = new GoogleGenAI({ apiKey: apiKey || "" });

// Using Flash for speed.
const MODEL = 'gemini-3-flash-preview'; 

// Caches
const eventCache = new Map<string, { summary: string, url: string }>();
const candidateCache = new Map<string, GeminiPersonResponse[]>();
const enrichmentCache = new Map<string, { description: string, wikipediaQuery: string }>();

/**
 * Finds historical figures who died on a specific date.
 * OPTIMIZED STRATEGY:
 * 1. Check Cache.
 * 2. Single "Best Effort" API call with JSON Schema (Basics only).
 * 3. Lazy Load Descriptions in parallel.
 */
export const findPreviousLifeCandidates = async (
  targetDate: string,
  deathCountry: string,
  excludeNames: string[],
  onCandidateFound: (candidate: GeminiPersonResponse) => void,
  onCandidateUpdate: (candidate: GeminiPersonResponse) => void
): Promise<void> => {

  // 1. Check Cache
  const cacheKey = `${targetDate}-${deathCountry}`;
  if (candidateCache.has(cacheKey)) {
    const cachedCandidates = candidateCache.get(cacheKey)!;
    const available = cachedCandidates.filter(c => !excludeNames.includes(c.name));

    if (available.length > 0) {
      console.log("Serving candidates from cache");
      available.forEach(c => onCandidateFound(c));
      return;
    }
  }

  // 2. Define Schema (Basics Only) - Faster generation
  const candidateSchema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        name: { type: Type.STRING },
        birthDate: { type: Type.STRING, description: "YYYY-MM-DD format" },
        birthCountry: { type: Type.STRING },
        deathDate: { type: Type.STRING, description: "YYYY-MM-DD format" },
        deathPlace: { type: Type.STRING },
        deathCountry: { type: Type.STRING },
      },
      required: ["name", "birthDate", "birthCountry", "deathDate", "deathPlace", "deathCountry"]
    }
  };

  // 3. Unified Prompt
  const prompt = `
    TASK: Find 2 famous historical figures whose death date connects to the date: ${targetDate}.

    PRIORITY 1: Exact Match. Find people who died on exactly ${targetDate}. Use Google Search with query "site:wikipedia.org died on ${targetDate}" to verify.
    PRIORITY 2: Near Match. If NO exact matches are found, find people who died in the same MONTH and YEAR (${targetDate.slice(0, 7)}).

    CONTEXT:
    - Prioritize figures who died in '${deathCountry}' if available.
    - DO NOT include: ${excludeNames.join(", ")}.

    OUTPUT:
    Return a JSON Array obeying the schema. Return ONLY the basic biographical data.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: candidateSchema,
      }
    });

    const jsonText = response.text;
    if (!jsonText) throw new Error("No response text generated");

    const candidates = JSON.parse(jsonText) as GeminiPersonResponse[];

    // Extract sources
    const sources: { title: string, url: string }[] = [];
    if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
        response.candidates[0].groundingMetadata.groundingChunks.forEach(c => {
            if (c.web?.uri && c.web?.title) {
                sources.push({ title: c.web.title, url: c.web.uri });
            }
        });
    }

    // Process Basics and Emit immediately
    const validCandidates = candidates.map((c, index) => ({
        ...c,
        id: `temp-${Date.now()}-${index}`,
        sources: sources.length > 0 ? sources : undefined
    }));

    // Emit basics
    validCandidates.forEach(c => onCandidateFound(c));

    // 4. Parallel Execution: Lazy Load Details
    // We don't await this blocking the function return, we let it update asynchronously
    // But for the cache logic, we might want to wait. 
    // To keep UI snappy, we fire and forget, but we need to update the cache eventually.

    const enrichmentPromises = validCandidates.map(async (candidate) => {
        const enriched = await enrichCandidate(candidate);
        onCandidateUpdate(enriched);
        return enriched;
    });

    // Wait for all enrichments to complete only to update the main cache
    Promise.all(enrichmentPromises).then(completedCandidates => {
        if (completedCandidates.length > 0) {
             const existing = candidateCache.get(cacheKey) || [];
             const combined = [...existing, ...completedCandidates].filter((v, i, a) => a.findIndex(t => t.name === v.name) === i);
             candidateCache.set(cacheKey, combined);
        }
    });

  } catch (e) {
    console.error("Candidate generation failed:", e);
  }
};

/**
 * Lazy loads description and wiki query for a candidate.
 */
const enrichCandidate = async (candidate: GeminiPersonResponse): Promise<GeminiPersonResponse> => {
    if (enrichmentCache.has(candidate.name)) {
        return { ...candidate, ...enrichmentCache.get(candidate.name) };
    }

    const prompt = `
        Write a short, exciting description (under 15 words) for historical figure: ${candidate.name} (${candidate.birthDate} - ${candidate.deathDate}).
        Also provide the best Wikipedia search query for them.
    `;

    const schema = {
        type: Type.OBJECT,
        properties: {
            description: { type: Type.STRING },
            wikipediaQuery: { type: Type.STRING }
        },
        required: ["description", "wikipediaQuery"]
    };

    try {
        const response = await ai.models.generateContent({
            model: MODEL,
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: schema
            }
        });

        if (response.text) {
            const data = JSON.parse(response.text);
            enrichmentCache.set(candidate.name, data);
            return { ...candidate, ...data };
        }
    } catch (e) {
        console.warn("Enrichment failed for", candidate.name);
    }

    // Fallback if enrichment fails
    return { 
        ...candidate, 
        description: "A mysterious figure from the past.", 
        wikipediaQuery: candidate.name 
    };
};

/**
 * Returns historical events from local database only.
 */
export const getHistoricalEvents = async (
    birthYear: string,
    deathYear: string,
    country: string
): Promise<string[]> => {
    const bYear = parseInt(birthYear);
    if (!isNaN(bYear)) {
        let events = getFallbackEvents(bYear);
        events = events.sort((a, b) => {
            const yearA = parseInt(a.match(/\((\d{4})\)/)?.[1] || "0");
            const yearB = parseInt(b.match(/\((\d{4})\)/)?.[1] || "0");
            return yearB - yearA;
        });
        return events.slice(0, 24);
    }
    return getFallbackEvents(1900).slice(0, 24);
}

