  };

  try {
    const response = await ai.models.generateContent({
        model: MODEL,
        contents: prompt,
        config: { 
            responseMimeType: "application/json",
            responseSchema: eventSchema
        }
    });

    if (response.text) {
        const data = JSON.parse(response.text);
        if (data.summary && data.url) {
            eventCache.set(eventName, data);
        }
        return data;
    }
    return null;
  } catch (e) {
    return null;
  }
};

import React, { useState, useEffect } from 'react';
import { LifeNode, SearchParams, GeminiPersonResponse } from './types';
import { findPreviousLifeCandidates, getHistoricalEvents } from './services/geminiService';
import InputForm from './components/InputForm';
import Timeline from './components/Timeline';
import SelectionArea from './components/SelectionArea';
import CosmicBackground from './components/CosmicBackground';
import ErrorBoundary from './components/ErrorBoundary';
import { History, RotateCcw, RefreshCw, Trash2 } from 'lucide-react';

const HISTORICAL_QUOTES = [
  "“We are not makers of history. We are made by history.” — Martin Luther King Jr.",
  "“The more you know about the past, the better prepared you are for the future.” — Theodore Roosevelt",
  "“Study the past if you would define the future.” — Confucius",
  "“People are trapped in history and history is trapped in them.” — James Baldwin",
  "“Every man is a quotation from all his ancestors.” — Ralph Waldo Emerson",
  "“What we do now echoes in eternity.” — Marcus Aurelius",
  "“The distinction between the past, present and future is only a stubbornly persistent illusion.” — Albert Einstein",
  "“Life can only be understood backwards; but it must be lived forwards.” — Søren Kierkegaard",
  "“To know nothing of what happened before you were born, is to remain ever a child.” — Cicero",
  "“Yesterday is history, tomorrow is a mystery, but today is a gift. That is why it is called the present.” — Master Oogway (attributed)",
  "“History is a set of lies agreed upon.” — Napoleon Bonaparte"
];

const STORAGE_KEY = 'my_previous_lives_v1';

const App: React.FC = () => {
  const [lives, setLives] = useState<LifeNode[]>([]);
  const [candidates, setCandidates] = useState<GeminiPersonResponse[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [initialParams, setInitialParams] = useState<SearchParams | null>(null);

  // Initialize with a random quote
  const [randomQuote] = useState(() => 
    HISTORICAL_QUOTES[Math.floor(Math.random() * HISTORICAL_QUOTES.length)]
  );

  // Persistence: Load State
  useEffect(() => {
    try {
        const saved = localStorage.getItem(STORAGE_KEY);
        if (saved) {
            const parsed = JSON.parse(saved);
            if (parsed.lives && Array.isArray(parsed.lives)) setLives(parsed.lives);
            if (parsed.candidates && Array.isArray(parsed.candidates)) setCandidates(parsed.candidates);
            if (parsed.initialParams) setInitialParams(parsed.initialParams);
        }
    } catch (e) {
        console.warn("Failed to load saved state", e);
    }
  }, []);

  // Persistence: Save State
  useEffect(() => {
    try {
        if (lives.length > 0) {
            localStorage.setItem(STORAGE_KEY, JSON.stringify({
                lives,
                candidates,
                initialParams
            }));
        }
    } catch (e) {
        console.warn("Failed to save state", e);
    }
  }, [lives, candidates, initialParams]);

  const startChain = async (params: SearchParams) => {
    setLoading(true);
    setError(null);
    setLives([]);
    setCandidates([]);
    setInitialParams(params);
    // Clear storage on new start
    localStorage.removeItem(STORAGE_KEY);

    const userNode: LifeNode = {
      id: 'user',
      name: 'You',
      birthDate: params.date,
      birthCountry: params.country,
      deathDate: 'Present',
      deathPlace: 'Present',
      deathCountry: params.country,
      description: 'The current manifestation of the soul.',
      isUser: true
    };

    setLives([userNode]);

    await fetchCandidatesForNode(userNode, [userNode]);
  };

  const fetchCandidatesForNode = async (
    currentNode: LifeNode, 
    currentLives: LifeNode[],
    extraExclusions: string[] = []
  ) => {
    setLoading(true);
    setError(null);
    setCandidates([]);

    try {
      const targetDate = currentNode.birthDate;
      const locationConstraint = currentNode.deathCountry || currentNode.birthCountry;

      const excludeNames = [...currentLives.map(l => l.name), ...extraExclusions];

      let count = 0;
      await findPreviousLifeCandidates(
        targetDate, 
        locationConstraint, 
        excludeNames,
        (candidate) => {
            // Callback when a BASIC candidate is found
            setCandidates(prev => {
                if (prev.some(c => c.name === candidate.name)) return prev;
                return [...prev, candidate];
            });
            count++;
        },
        (updatedCandidate) => {
            // Callback when a candidate is ENRICHED (Lazy Loaded)
            setCandidates(prev => prev.map(c => 
                c.name === updatedCandidate.name ? updatedCandidate : c
            ));
        }
      );

      if (count === 0) {
           // If search fails silently, the UI will show empty state or retry
      }

    } catch (err) {
      console.error(err);
      setError("The cosmic archives are currently unreachable. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleSelectCandidate = async (candidate: GeminiPersonResponse) => {
    // Get historical events from local fallback immediately
    const birthYear = candidate.birthDate.split('-')[0];
    const deathYear = candidate.deathDate === 'Present' ? new Date().getFullYear().toString() : candidate.deathDate.split('-')[0];
    const events = await getHistoricalEvents(birthYear, deathYear, candidate.deathCountry);

    const newNode: LifeNode = {
      id: `life-${Date.now()}`,
      name: candidate.name,
      birthDate: candidate.birthDate,
      birthCountry: candidate.birthCountry,
      deathDate: candidate.deathDate,
      deathPlace: candidate.deathPlace,
      deathCountry: candidate.deathCountry,
      description: candidate.description || "A figure from history.",
      wikipediaUrl: candidate.wikipediaQuery ? `https://en.wikipedia.org/wiki/${encodeURIComponent(candidate.wikipediaQuery)}` : undefined,
      isUser: false,
      historicalEvents: events,
      sources: candidate.sources
    };

    const newLives = [...lives, newNode];
    setLives(newLives);
    setCandidates([]); // Clear selection

    // Fetch next candidates
    await fetchCandidatesForNode(newNode, newLives);
  };

  const handleShuffle = () => {
    if (lives.length > 0) {
      const lastLife = lives[lives.length - 1];
      const currentCandidateNames = candidates.map(c => c.name);
      fetchCandidatesForNode(lastLife, lives, currentCandidateNames);
    }
  };

  const handleFullReset = () => {
    setLives([]);
    setCandidates([]);
    setError(null);
    setLoading(false);
    setInitialParams(null);
    localStorage.removeItem(STORAGE_KEY);
  };

  const handleRestart = () => {
    if (initialParams) {
        startChain(initialParams);
    }
  };

  // Stop bubbles if we have results OR if loading is finished (idle)
  const areCandidatesReady = candidates.length > 0 || error !== null;

  return (
    <ErrorBoundary>
        <div className="min-h-screen text-mystic-50 font-sans selection:bg-mystic-500 selection:text-white pb-20 overflow-x-hidden relative">
        <CosmicBackground />

        {/* Header */}
        <header className="p-6 border-b border-mystic-800/50 bg-mystic-950/60 backdrop-blur-md sticky top-0 z-50">
            <div className="max-w-6xl mx-auto flex items-center justify-between">
            <div className="flex items-center gap-3">
                <div className="bg-mystic-800/80 p-2 rounded-full border border-mystic-500/50 shadow-[0_0_15px_rgba(129,84,175,0.3)]">
                    <History className="w-6 h-6 text-mystic-200" />
                </div>
                <h1 className="text-2xl font-serif font-bold tracking-wide text-white drop-shadow-[0_2px_4px_rgba(0,0,0,0.5)]">My Previous Lives</h1>
            </div>
            {lives.length > 0 && (
                <div className="flex gap-2">
                    <button 
                        onClick={handleFullReset}
                        className="flex items-center gap-2 text-sm text-mystic-300 hover:text-white transition-colors bg-mystic-900/50 px-3 py-1.5 rounded-lg border border-mystic-700/50 hover:bg-mystic-800/50"
                        title="Start Over"
                    >
                        <RotateCcw className="w-4 h-4" /> <span className="hidden sm:inline">New Search</span>
                    </button>
                    <button 
                        onClick={() => { localStorage.removeItem(STORAGE_KEY); window.location.reload(); }}
                        className="flex items-center justify-center gap-2 text-sm text-red-300 hover:text-red-100 transition-colors bg-red-950/30 px-3 py-1.5 rounded-lg border border-red-900/50 hover:bg-red-900/50"
                        title="Clear History & Reload"
                    >
                        <Trash2 className="w-4 h-4" />
                    </button>
                </div>
            )}
            </div>
        </header>

        {/* Main Content */}
        <main className="container mx-auto px-4 pt-12 flex flex-col items-center relative z-10">
            {lives.length === 0 ? (
            <div className="max-w-xl w-full mx-auto mt-10">
                <InputForm onSubmit={startChain} isLoading={loading} />

                <div className="mt-12 text-center text-mystic-300 text-sm px-6">
                <p className="font-serif italic opacity-70">
                    {randomQuote}
                </p>
                </div>
            </div>
            ) : (
            <div className="relative w-full max-w-4xl">
                <Timeline lives={lives} candidatesReady={areCandidatesReady} />

                {/* The Selection Area appears at the end of the timeline */}
                <div className="mt-4 mb-8">
                    {/* Show SelectionArea if loading OR we have candidates OR error */}
                    {(loading || candidates.length > 0 || error) && (
                    <SelectionArea 
                        candidates={candidates}
                        isLoading={loading && candidates.length === 0} // Only show spinner if NO candidates yet
                        onSelect={handleSelectCandidate}
                        onShuffle={handleShuffle}
                    />
                    )}
                </div>

                {/* Error Message */}
                {error && !loading && candidates.length === 0 && (
                    <div className="max-w-lg mx-auto mt-8 p-6 bg-red-950/40 border border-red-800/50 rounded-xl text-red-200 text-center animate-fade-in-up backdrop-blur-sm">
                        <p className="mb-4">{error}</p>
                        <button 
                            onClick={handleShuffle}
                            className="text-sm px-4 py-2 bg-red-900/50 rounded-lg hover:bg-red-800/60 transition-colors"
                        >
                            Try connecting again
                        </button>
                    </div>
                )}

                {/* Restart Button */}
                {initialParams && !loading && (
                    <div className="flex justify-center mt-12 animate-fade-in-up">
                        <button
                            onClick={handleRestart}
                            className="flex items-center gap-2 px-6 py-3 bg-mystic-900/80 border border-mystic-600/50 rounded-full text-mystic-200 hover:bg-mystic-800 hover:text-white hover:border-mystic-400 transition-all shadow-[0_0_20px_rgba(0,0,0,0.3)] backdrop-blur-sm text-sm font-serif tracking-wider"
                        >
                            <RefreshCw className="w-4 h-4" />
                            Restart This Lineage
                        </button>
                    </div>
                )}
            </div>
            )}
        </main>
        </div>
    </ErrorBoundary>
  );
};

export default App;

