  // This is crucial for virtualization so they don't re-animate when scrolling back up.
  const [visibleBubbles, setVisibleBubbles] = useState<number>(
    isLast ? 0 : (life.historicalEvents?.length || 0)
  );

  // Modal state
  const [selectedEvent, setSelectedEvent] = useState<string | null>(null);
