import React, { useEffect, useState, useMemo, useRef } from 'react';
import { LifeNode } from '../types';
import { MapPin, Calendar, ExternalLink, Skull, BookOpen, X, Info, Globe } from 'lucide-react';
import { getEventDetails } from '../services/geminiService';

interface LifeCardProps {
  life: LifeNode;
  index: number;
  isLast: boolean;
  stopBubbles: boolean; // Signal to stop showing new bubbles
}

// Pseudo-random number generator seeded by string
const getSeededRandom = (seedStr: string) => {
  let h = 0x811c9dc5;
  for (let i = 0; i < seedStr.length; i++) {
    h ^= seedStr.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return function() {
    h = Math.imul(h ^ (h >>> 16), 2246822507);
    h = Math.imul(h ^ (h >>> 13), 3266489909);
    return (h >>> 0) / 4294967296;
  }
};

const LifeCard: React.FC<LifeCardProps> = ({ life, index, isLast, stopBubbles }) => {
  // If it's not the last card, we assume it's "historical" and show all bubbles immediately.
  const [visibleBubbles, setVisibleBubbles] = useState<number>(
    isLast ? 0 : (life.historicalEvents?.length || 0)
  );

  // Modal state
  const [selectedEvent, setSelectedEvent] = useState<string | null>(null);
  const [eventDetails, setEventDetails] = useState<{summary: string, url: string} | null>(null);
  const [loadingDetails, setLoadingDetails] = useState(false);
  const eventModalRef = useRef<HTMLDivElement>(null);

  // Map Modal state
  const [showMap, setShowMap] = useState(false);
  const mapModalRef = useRef<HTMLDivElement>(null);

  // Focus management
  const lastFocusedElement = useRef<HTMLElement | null>(null);

  // Stagger animation delay based on index for the main card
  const animationDelay = isLast ? `${index * 0.2}s` : '0s';

  // --- POSITIONING LOGIC ---
  const bubbleConfig = useMemo(() => {
    if (!life.historicalEvents) return [];

    const rng = getSeededRandom(life.id);
    const count = life.historicalEvents.length;

    // We define 6 slots: 0=TopL, 1=TopR, 2=MidL, 3=MidR, 4=BotL, 5=BotR
    // We create a deck of slots and shuffle them to assign to events
    const slots = [0, 1, 2, 3, 4, 5];

    // Fisher-Yates shuffle with seeded RNG
    for (let i = slots.length - 1; i > 0; i--) {
        const j = Math.floor(rng() * (i + 1));
        [slots[i], slots[j]] = [slots[j], slots[i]];
    }

    return life.historicalEvents.map((_, i) => {
        // Cycle through slots if we have more events than slots (unlikely with limit 6, but safe)
        const slot = slots[i % 6];
        const isLeft = slot % 2 === 0;
        const verticalTier = Math.floor(slot / 2); // 0, 1, or 2

        // Base positions
        let topBase = 0;
        if (verticalTier === 0) topBase = -10; // Top: -10%
        if (verticalTier === 1) topBase = 45;  // Mid: 45%
        if (verticalTier === 2) topBase = 95;  // Bot: 95%

        // Add Random Variance
        // Y variance: +/- 10%
        const topVariance = (rng() * 20) - 10;
        const finalTop = Math.max(-20, Math.min(120, topBase + topVariance));

        // X variance (Distance from center)
        // Base distance is around 280px-350px from center on desktop
        // We calculate this as 'left' or 'right' CSS absolute positions relative to the card center
        // Note: The parent container is centered flex, but bubbles are absolute relative to the wrapper
        // wrapper width is w-full (max-w-4xl). Card is max-w-2xl (approx 672px).
        // Center is 50%. Card edge is roughly +/- 336px.
        // We want bubbles to sit starting at around 360px from center.

        const baseDistance = 340; // px from center
        const distanceVariance = (rng() * 80); // 0 to 80px extra
        const finalDistance = baseDistance + distanceVariance;

        return {
            isLeft,
            style: {
                top: `${finalTop}%`,
                [isLeft ? 'right' : 'left']: `50%`, // Anchor to center
                transform: `translateX(${isLeft ? -finalDistance : finalDistance}px) translateY(-50%)`, // Push out
                // Store raw distance for animation calc
                '--dist': `${finalDistance}px`,
                '--dir': isLeft ? -1 : 1
            } as React.CSSProperties
        };
    });
  }, [life.id, life.historicalEvents]);


  // Logic to show bubbles one by one
  useEffect(() => {
    if (!isLast || !life.historicalEvents) {
        if (!isLast && life.historicalEvents) {
            setVisibleBubbles(life.historicalEvents.length);
        }
        return;
    }

    const interval = setInterval(() => {
        if (stopBubbles) {
            clearInterval(interval);
            return;
        }
        setVisibleBubbles(prev => {
            if (life.historicalEvents && prev < life.historicalEvents.length) {
                return prev + 1;
            }
            clearInterval(interval);
            return prev;
        });
    }, 4000); // 4s interval

    return () => clearInterval(interval);
