                    ref={mapModalRef}
                    tabIndex={-1}
                    className="relative z-10 bg-mystic-900 border border-mystic-500 rounded-xl overflow-hidden max-w-2xl w-full shadow-[0_0_50px_rgba(0,0,0,0.5)] animate-fade-in-up focus:outline-none"
                >
                    <div className="p-4 bg-mystic-800 border-b border-mystic-700 flex justify-between items-center">
                        <h3 id="map-modal-title" className="text-lg font-serif font-bold text-white flex items-center gap-2">
                            <Globe className="w-4 h-4 text-mystic-400"/>
                            {life.birthCountry}
                        </h3>
                        <button onClick={() => setShowMap(false)} className="text-mystic-400 hover:text-white focus:outline-none focus:ring-2 focus:ring-mystic-400 rounded p-1">
