                    <div className="h-[400px] w-full bg-mystic-950 flex items-center justify-center relative group">
                        <iframe 
                            width="100%" 
                            height="100%" 
                            frameBorder="0" 
                            scrolling="no" 
                            src={`https://maps.google.com/maps?q=${encodeURIComponent(life.birthCountry)}&t=m&z=4&output=embed&iwloc=near`}
                            title={`${life.birthCountry} Map`}
                            className="opacity-90 hover:opacity-100 transition-opacity"
