                          <div className="text-sm text-gray-600">{life.birthCountry}</div>
                      </div>
                      <div className="bg-mystic-50/50 p-3 rounded-lg border border-mystic-200">
                          <div className="flex items-center gap-2 text-red-800 mb-1 font-bold text-xs uppercase tracking-wider">
                              <Skull className="w-3 h-3" /> Death
                          </div>
                          <div className="font-serif text-lg">{life.deathDate}</div>
                          <div className="text-sm text-gray-600">{life.deathPlace}</div>
                      </div>
                  </div>

                  <div className="text-gray-700 font-serif leading-relaxed italic border-l-4 border-mystic-400 pl-4 py-1">
                      {life.description ? (
                          `"${life.description}"`
                      ) : (
                          <div className="space-y-2 opacity-30">
                              <div className="h-3 bg-gray-400 rounded w-full"></div>
                              <div className="h-3 bg-gray-400 rounded w-5/6"></div>
                          </div>
                      )}
                  </div>

                  {/* Sources Section if available */}
                  {life.sources && life.sources.length > 0 && (
                    <div className="mt-4 pt-2 border-t border-mystic-200">
                        <div className="flex items-center gap-1 text-xs text-mystic-600 mb-1">
                          <BookOpen className="w-3 h-3" /> Sources
                        </div>
                        <div className="flex flex-wrap gap-2">
                          {life.sources.slice(0, 2).map((src, idx) => (
                            <a 
                              key={idx} 
                              href={src.url} 
                              target="_blank" 
                              rel="noopener noreferrer"
                              className="text-[10px] text-blue-600 hover:underline truncate max-w-[200px] focus:outline-none focus:underline"
                            >
                              {src.title}
                            </a>
                          ))}
                        </div>
                    </div>
                  )}

                  <div className="mt-4 pt-4 border-t border-gray-200 text-xs text-gray-500 text-center">
                      Reincarnated as next soul on {life.deathDate}
                  </div>
              </div>
            </div>
        </div>

        {/* Connection Logic */}
        <div className="h-12 w-0.5 bg-gradient-to-b from-mystic-700 to-mystic-500 my-2"></div>
      </div>

      {/* Historical Card Map Modal */}
      {showMap && (
        <div className="fixed inset-0 z-50 flex items-center justify-center px-4" role="dialog" aria-modal="true" aria-labelledby="hist-map-modal-title">
            <div 
                className="absolute inset-0 bg-mystic-950/80 backdrop-blur-sm transition-opacity"
                onClick={() => setShowMap(false)}
            ></div>
            <div 
                ref={mapModalRef}
                tabIndex={-1}
                className="relative z-10 bg-mystic-900 border border-mystic-500 rounded-xl overflow-hidden max-w-2xl w-full shadow-[0_0_50px_rgba(0,0,0,0.5)] animate-fade-in-up focus:outline-none"
            >
                <div className="p-4 bg-mystic-800 border-b border-mystic-700 flex justify-between items-center">
                    <h3 id="hist-map-modal-title" className="text-lg font-serif font-bold text-white flex items-center gap-2">
                        <Globe className="w-4 h-4 text-mystic-400"/>
                        {life.birthCountry}
                    </h3>
                    <button onClick={() => setShowMap(false)} className="text-mystic-400 hover:text-white focus:outline-none focus:ring-2 focus:ring-mystic-400 rounded p-1">
                        <X className="w-5 h-5" />
                    </button>
                </div>
                <div className="h-[400px] w-full bg-mystic-950 flex items-center justify-center relative group">
                    <iframe 
                        width="100%" 
                        height="100%" 
                        frameBorder="0" 
                        scrolling="no" 
                        src={`https://maps.google.com/maps?q=${encodeURIComponent(life.birthCountry)}&t=m&z=4&output=embed&iwloc=near`}
                        title={`${life.birthCountry} Map`}
                        className="opacity-90 hover:opacity-100 transition-opacity"
                    ></iframe>
                </div>
            </div>
        </div>
      )}

      {/* Event Details Modal */}
      {selectedEvent && (
        <div className="fixed inset-0 z-50 flex items-center justify-center px-4" role="dialog" aria-modal="true" aria-labelledby="event-modal-title">
          <div 
            className="absolute inset-0 bg-mystic-950/90 backdrop-blur-md transition-opacity"
            onClick={() => setSelectedEvent(null)}
          ></div>
          <div 
            ref={eventModalRef}
            tabIndex={-1}
            className="relative z-10 bg-mystic-900 border border-mystic-500 rounded-xl p-6 max-w-lg w-full shadow-[0_0_50px_rgba(129,84,175,0.4)] animate-fade-in-up focus:outline-none"
          >
            <div className="flex justify-between items-start mb-4">
              <h3 id="event-modal-title" className="text-xl font-serif font-bold text-white leading-tight pr-4">
                {selectedEvent}
              </h3>
              <button onClick={() => setSelectedEvent(null)} className="text-mystic-400 hover:text-white focus:outline-none focus:ring-2 focus:ring-mystic-400 rounded p-1">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="text-mystic-200 mb-6 leading-relaxed min-h-[80px]">
              {loadingDetails ? (
                <div className="flex items-center gap-2 text-mystic-400 italic">
                  <div className="w-4 h-4 border-2 border-mystic-400 border-t-transparent rounded-full animate-spin"></div>
                  Consulting archives...
                </div>
              ) : eventDetails ? (
                <p>{eventDetails.summary}</p>
              ) : (
                <p className="italic text-mystic-400">Details currently unavailable in the archives.</p>
              )}
            </div>

            {eventDetails?.url && (
              <a 
                href={eventDetails.url}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex items-center gap-2 text-sm text-yellow-300 hover:text-yellow-200 transition-colors focus:outline-none focus:underline"
              >
                Read more on Wikipedia <ExternalLink className="w-4 h-4" />
              </a>
            )}
          </div>
        </div>
      )}
    </>
  );
};

export default React.memo(LifeCard);
